(63, 'chapter', 'created', 'App\\Models\\Chapter', 'created', 1, NULL, NULL, '{\"attributes\":{\"id\":1,\"section_id\":1,\"title\":\"Introduction \\u00e0 HTML5\",\"content\":\"HTML5 est le langage standard pour cr\\u00e9er des pages web. Dans ce chapitre, nous allons voir les balises essentielles : structure de base, titres, paragraphes, listes, liens et images. Vous apprendrez \\u00e0 organiser votre contenu avec des balises s\\u00e9mantiques comme header, nav, main, section, article et footer.\",\"content_type\":\"video\",\"media_url\":null,\"video_url\":null,\"cover_image\":null,\"markdown_file\":null,\"processing_status\":null,\"processing_error\":null,\"processing_metadata\":null,\"processing_started_at\":null,\"processed_at\":null,\"duration_minutes\":45,\"order_position\":1,\"is_free\":true,\"is_active\":true,\"description\":\"D\\u00e9couvrez les bases du langage HTML5.\",\"created_at\":\"2026-07-27T20:42:29.000000Z\",\"updated_at\":\"2026-07-27T20:42:29.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(64, 'chapter', 'created', 'App\\Models\\Chapter', 'created', 2, NULL, NULL, '{\"attributes\":{\"id\":2,\"section_id\":1,\"title\":\"CSS3 - Mise en page et design\",\"content\":\"Le CSS3 permet de donner du style \\u00e0 vos pages HTML. Nous aborderons les s\\u00e9lecteurs, le mod\\u00e8le de bo\\u00eete, le flexbox, le grid, les animations et les media queries pour le responsive design. Vous serez capable de cr\\u00e9er des mises en page modernes et adaptatives.\",\"content_type\":\"video\",\"media_url\":null,\"video_url\":null,\"cover_image\":null,\"markdown_file\":null,\"processing_status\":null,\"processing_error\":null,\"processing_metadata\":null,\"processing_started_at\":null,\"processed_at\":null,\"duration_minutes\":60,\"order_position\":2,\"is_free\":false,\"is_active\":true,\"description\":\"Apprenez \\u00e0 styliser vos pages web avec CSS3.\",\"created_at\":\"2026-07-27T20:42:29.000000Z\",\"updated_at\":\"2026-07-27T20:42:29.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(65, 'chapter', 'created', 'App\\Models\\Chapter', 'created', 3, NULL, NULL, '{\"attributes\":{\"id\":3,\"section_id\":1,\"title\":\"JavaScript - Les Fondamentaux\",\"content\":\"JavaScript est le langage de programmation du web. Ce chapitre couvre les variables, les types de donn\\u00e9es, les fonctions, les objets, les tableaux, les boucles et les conditions. Vous apprendrez \\u00e0 manipuler le DOM et \\u00e0 g\\u00e9rer les \\u00e9v\\u00e9nements utilisateur.\",\"content_type\":\"text\",\"media_url\":null,\"video_url\":null,\"cover_image\":null,\"markdown_file\":null,\"processing_status\":null,\"processing_error\":null,\"processing_metadata\":null,\"processing_started_at\":null,\"processed_at\":null,\"duration_minutes\":90,\"order_position\":3,\"is_free\":false,\"is_active\":true,\"description\":\"Les bases de la programmation JavaScript.\",\"created_at\":\"2026-07-27T20:42:29.000000Z\",\"updated_at\":\"2026-07-27T20:42:29.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(66, 'chapter', 'created', 'App\\Models\\Chapter', 'created', 4, NULL, NULL, '{\"attributes\":{\"id\":4,\"section_id\":2,\"title\":\"Introduction \\u00e0 PHP 8\",\"content\":\"PHP 8 apporte des am\\u00e9liorations significatives. Nous verrons la syntaxe moderne, les types stricts, les attributs, les enum\\u00e9rations, et les fonctionnalit\\u00e9s orient\\u00e9es objet. Vous comprendrez comment PHP fonctionne c\\u00f4t\\u00e9 serveur.\",\"content_type\":\"video\",\"media_url\":null,\"video_url\":null,\"cover_image\":null,\"markdown_file\":null,\"processing_status\":null,\"processing_error\":null,\"processing_metadata\":null,\"processing_started_at\":null,\"processed_at\":null,\"duration_minutes\":60,\"order_position\":1,\"is_free\":false,\"is_active\":true,\"description\":\"Les bases de PHP moderne.\",\"created_at\":\"2026-07-27T20:42:29.000000Z\",\"updated_at\":\"2026-07-27T20:42:29.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(67, 'chapter', 'created', 'App\\Models\\Chapter', 'created', 5, NULL, NULL, '{\"attributes\":{\"id\":5,\"section_id\":2,\"title\":\"Laravel - Routing & Controllers\",\"content\":\"Laravel est le framework PHP le plus populaire. Ce chapitre vous montre comment configurer les routes, cr\\u00e9er des contr\\u00f4leurs, g\\u00e9rer les requ\\u00eates et les r\\u00e9ponses, et utiliser les middlewares. Vous construirez votre premi\\u00e8re API REST.\",\"content_type\":\"video\",\"media_url\":null,\"video_url\":null,\"cover_image\":null,\"markdown_file\":null,\"processing_status\":null,\"processing_error\":null,\"processing_metadata\":null,\"processing_started_at\":null,\"processed_at\":null,\"duration_minutes\":90,\"order_position\":2,\"is_free\":false,\"is_active\":true,\"description\":\"Les bases du framework Laravel.\",\"created_at\":\"2026-07-27T20:42:29.000000Z\",\"updated_at\":\"2026-07-27T20:42:29.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(68, 'chapter', 'created', 'App\\Models\\Chapter', 'created', 6, NULL, NULL, '{\"attributes\":{\"id\":6,\"section_id\":2,\"title\":\"Eloquent ORM & Migrations\",\"content\":\"Eloquent est l\'ORM de Laravel. Vous apprendrez \\u00e0 cr\\u00e9er des migrations, des mod\\u00e8les, des relations (belongsTo, hasMany, belongsToMany), et \\u00e0 effectuer des requ\\u00eates avanc\\u00e9es. La gestion des bases de donn\\u00e9es n\'aura plus de secrets pour vous.\",\"content_type\":\"text\",\"media_url\":null,\"video_url\":null,\"cover_image\":null,\"markdown_file\":null,\"processing_status\":null,\"processing_error\":null,\"processing_metadata\":null,\"processing_started_at\":null,\"processed_at\":null,\"duration_minutes\":75,\"order_position\":3,\"is_free\":false,\"is_active\":true,\"description\":\"La couche base de donn\\u00e9es de Laravel.\",\"created_at\":\"2026-07-27T20:42:29.000000Z\",\"updated_at\":\"2026-07-27T20:42:29.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:29', '2026-07-28 00:42:29');
