(143, 'question', 'created', 'App\\Models\\Question', 'created', 2, NULL, NULL, '{\"attributes\":{\"id\":2,\"exam_id\":1,\"question_text\":\"Qu\'est-ce que le Flexbox en CSS ?\",\"question_type\":\"single_choice\",\"points\":10,\"order_position\":2,\"explanation\":\"Flexbox est un module de mise en page CSS qui permet d\'aligner et de distribuer efficacement les \\u00e9l\\u00e9ments dans un conteneur.\",\"image\":null,\"is_required\":true,\"created_at\":\"2026-07-27T20:42:30.000000Z\",\"updated_at\":\"2026-07-27T20:42:30.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
