(147, 'question', 'created', 'App\\Models\\Question', 'created', 6, NULL, NULL, '{\"attributes\":{\"id\":6,\"exam_id\":1,\"question_text\":\"Tailwind CSS est un framework CSS utility-first.\",\"question_type\":\"true_false\",\"points\":5,\"order_position\":6,\"explanation\":\"Vrai. Tailwind CSS adopte une approche utility-first contrairement \\u00e0 Bootstrap qui est bas\\u00e9 sur des composants.\",\"image\":null,\"is_required\":true,\"created_at\":\"2026-07-27T20:42:30.000000Z\",\"updated_at\":\"2026-07-27T20:42:30.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(148, 'question', 'created', 'App\\Models\\Question', 'created', 7, NULL, NULL, '{\"attributes\":{\"id\":7,\"exam_id\":1,\"question_text\":\"En HTTP, une requ\\u00eate GET transmet les param\\u00e8tres dans l\'URL tandis qu\'une requ\\u00eate POST les transmet dans le corps de la requ\\u00eate.\",\"question_type\":\"true_false\",\"points\":10,\"order_position\":7,\"explanation\":\"GET r\\u00e9cup\\u00e8re des donn\\u00e9es (visible dans l\'URL, limit\\u00e9 en taille), POST envoie des donn\\u00e9es (dans le corps, pas de limite de taille).\",\"image\":null,\"is_required\":true,\"created_at\":\"2026-07-27T20:42:30.000000Z\",\"updated_at\":\"2026-07-27T20:42:30.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
