(153, 'question', 'created', 'App\\Models\\Question', 'created', 12, NULL, NULL, '{\"attributes\":{\"id\":12,\"exam_id\":2,\"question_text\":\"Quel est l\'objectif principal du marketing de contenu ?\",\"question_type\":\"single_choice\",\"points\":10,\"order_position\":2,\"explanation\":\"Le marketing de contenu vise \\u00e0 attirer et engager une audience cible en cr\\u00e9ant du contenu pertinent et de valeur.\",\"image\":null,\"is_required\":true,\"created_at\":\"2026-07-27T20:42:30.000000Z\",\"updated_at\":\"2026-07-27T20:42:30.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(154, 'question', 'created', 'App\\Models\\Question', 'created', 13, NULL, NULL, '{\"attributes\":{\"id\":13,\"exam_id\":2,\"question_text\":\"Quels sont les facteurs de ranking Google les plus importants ? (Plusieurs r\\u00e9ponses)\",\"question_type\":\"multiple_choice\",\"points\":15,\"order_position\":3,\"explanation\":\"La qualit\\u00e9 du contenu, les backlinks, l\'exp\\u00e9rience utilisateur et la vitesse de chargement sont des facteurs cl\\u00e9s.\",\"image\":null,\"is_required\":true,\"created_at\":\"2026-07-27T20:42:30.000000Z\",\"updated_at\":\"2026-07-27T20:42:30.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(155, 'question', 'created', 'App\\Models\\Question', 'created', 14, NULL, NULL, '{\"attributes\":{\"id\":14,\"exam_id\":2,\"question_text\":\"Le CPC (Co\\u00fbt Par Clic) est une m\\u00e9trique utilis\\u00e9e uniquement pour le SEO.\",\"question_type\":\"true_false\",\"points\":5,\"order_position\":4,\"explanation\":\"Faux. Le CPC est une m\\u00e9trique utilis\\u00e9e pour les campagnes publicitaires payantes (SEA), pas pour le SEO.\",\"image\":null,\"is_required\":true,\"created_at\":\"2026-07-27T20:42:30.000000Z\",\"updated_at\":\"2026-07-27T20:42:30.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(156, 'question', 'created', 'App\\Models\\Question', 'created', 15, NULL, NULL, '{\"attributes\":{\"id\":15,\"exam_id\":2,\"question_text\":\"D\\u00e9crivez les \\u00e9tapes pour cr\\u00e9er une campagne Google Ads performante.\",\"question_type\":\"single_choice\",\"points\":25,\"order_position\":5,\"explanation\":\"D\\u00e9finir les objectifs, choisir les mots-cl\\u00e9s, cr\\u00e9er des annonces, d\\u00e9finir le budget, cibler l\'audience, et analyser les performances.\",\"image\":null,\"is_required\":true,\"created_at\":\"2026-07-27T20:42:30.000000Z\",\"updated_at\":\"2026-07-27T20:42:30.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(157, 'question', 'created', 'App\\Models\\Question', 'created', 16, NULL, NULL, '{\"attributes\":{\"id\":16,\"exam_id\":2,\"question_text\":\"Qu\'est-ce qu\'un taux d\'engagement sur les r\\u00e9seaux sociaux ?\",\"question_type\":\"single_choice\",\"points\":10,\"order_position\":6,\"explanation\":\"Le taux d\'engagement mesure les interactions (likes, commentaires, partages) rapport\\u00e9es au nombre d\'abonn\\u00e9s ou d\'impressions.\",\"image\":null,\"is_required\":true,\"created_at\":\"2026-07-27T20:42:30.000000Z\",\"updated_at\":\"2026-07-27T20:42:30.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(158, 'question', 'created', 'App\\Models\\Question', 'created', 17, NULL, NULL, '{\"attributes\":{\"id\":17,\"exam_id\":2,\"question_text\":\"Citez trois outils de gestion des r\\u00e9seaux sociaux.\",\"question_type\":\"single_choice\",\"points\":10,\"order_position\":7,\"explanation\":\"Hootsuite, Buffer, Later, Sprout Social, et HubSpot sont des outils populaires.\",\"image\":null,\"is_required\":false,\"created_at\":\"2026-07-27T20:42:30.000000Z\",\"updated_at\":\"2026-07-27T20:42:30.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(159, 'question', 'created', 'App\\Models\\Question', 'created', 18, NULL, NULL, '{\"attributes\":{\"id\":18,\"exam_id\":2,\"question_text\":\"Qu\'est-ce que le retargeting ?\",\"question_type\":\"single_choice\",\"points\":15,\"order_position\":8,\"explanation\":\"Le retargeting consiste \\u00e0 cibler les utilisateurs qui ont d\\u00e9j\\u00e0 visit\\u00e9 votre site avec des publicit\\u00e9s personnalis\\u00e9es.\",\"image\":null,\"is_required\":true,\"created_at\":\"2026-07-27T20:42:30.000000Z\",\"updated_at\":\"2026-07-27T20:42:30.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(160, 'question', 'created', 'App\\Models\\Question', 'created', 19, NULL, NULL, '{\"attributes\":{\"id\":19,\"exam_id\":3,\"question_text\":\"Quelle biblioth\\u00e8que Python est utilis\\u00e9e pour le calcul num\\u00e9rique ?\",\"question_type\":\"single_choice\",\"points\":10,\"order_position\":1,\"explanation\":\"NumPy est la biblioth\\u00e8que fondamentale pour le calcul num\\u00e9rique en Python.\",\"image\":null,\"is_required\":true,\"created_at\":\"2026-07-27T20:42:30.000000Z\",\"updated_at\":\"2026-07-27T20:42:30.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(161, 'question', 'created', 'App\\Models\\Question', 'created', 20, NULL, NULL, '{\"attributes\":{\"id\":20,\"exam_id\":3,\"question_text\":\"\\u00c0 quoi sert la m\\u00e9thode groupby() dans Pandas ?\",\"question_type\":\"single_choice\",\"points\":10,\"order_position\":2,\"explanation\":\"groupby() permet de regrouper les donn\\u00e9es selon une ou plusieurs colonnes pour appliquer des fonctions d\'agr\\u00e9gation.\",\"image\":null,\"is_required\":true,\"created_at\":\"2026-07-27T20:42:30.000000Z\",\"updated_at\":\"2026-07-27T20:42:30.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(162, 'question', 'created', 'App\\Models\\Question', 'created', 21, NULL, NULL, '{\"attributes\":{\"id\":21,\"exam_id\":3,\"question_text\":\"Quels sont les types d\'apprentissage automatique ? (Plusieurs r\\u00e9ponses)\",\"question_type\":\"multiple_choice\",\"points\":15,\"order_position\":3,\"explanation\":\"Les trois principaux types sont l\'apprentissage supervis\\u00e9, non supervis\\u00e9 et par renforcement.\",\"image\":null,\"is_required\":true,\"created_at\":\"2026-07-27T20:42:30.000000Z\",\"updated_at\":\"2026-07-27T20:42:30.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(163, 'question', 'created', 'App\\Models\\Question', 'created', 22, NULL, NULL, '{\"attributes\":{\"id\":22,\"exam_id\":3,\"question_text\":\"Dans un arbre de d\\u00e9cision, plus la profondeur est grande, meilleur est le mod\\u00e8le.\",\"question_type\":\"true_false\",\"points\":5,\"order_position\":4,\"explanation\":\"Faux. Une trop grande profondeur entra\\u00eene du surapprentissage (overfitting). Il faut trouver le bon \\u00e9quilibre.\",\"image\":null,\"is_required\":true,\"created_at\":\"2026-07-27T20:42:30.000000Z\",\"updated_at\":\"2026-07-27T20:42:30.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(164, 'question', 'created', 'App\\Models\\Question', 'created', 23, NULL, NULL, '{\"attributes\":{\"id\":23,\"exam_id\":3,\"question_text\":\"Expliquez la diff\\u00e9rence entre le surapprentissage (overfitting) et le sous-apprentissage (underfitting).\",\"question_type\":\"single_choice\",\"points\":20,\"order_position\":5,\"explanation\":\"Overfitting : le mod\\u00e8le apprend trop bien les donn\\u00e9es d\'entra\\u00eenement mais g\\u00e9n\\u00e9ralise mal. Underfitting : le mod\\u00e8le est trop simple et ne capture pas les patterns.\",\"image\":null,\"is_required\":true,\"created_at\":\"2026-07-27T20:42:30.000000Z\",\"updated_at\":\"2026-07-27T20:42:30.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(165, 'question', 'created', 'App\\Models\\Question', 'created', 24, NULL, NULL, '{\"attributes\":{\"id\":24,\"exam_id\":3,\"question_text\":\"Qu\'est-ce que la validation crois\\u00e9e (cross-validation) ?\",\"question_type\":\"single_choice\",\"points\":10,\"order_position\":6,\"explanation\":\"La validation crois\\u00e9e divise les donn\\u00e9es en plusieurs plis pour \\u00e9valuer la performance du mod\\u00e8le de mani\\u00e8re robuste.\",\"image\":null,\"is_required\":true,\"created_at\":\"2026-07-27T20:42:30.000000Z\",\"updated_at\":\"2026-07-27T20:42:30.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:30', '2026-07-28 00:42:30');
