(166, 'question', 'created', 'App\\Models\\Question', 'created', 25, NULL, NULL, '{\"attributes\":{\"id\":25,\"exam_id\":3,\"question_text\":\"Quelle m\\u00e9trique est appropri\\u00e9e pour \\u00e9valuer un mod\\u00e8le de classification binaire d\\u00e9s\\u00e9quilibr\\u00e9 ?\",\"question_type\":\"single_choice\",\"points\":10,\"order_position\":7,\"explanation\":\"Le F1-score est la meilleure m\\u00e9trique pour les donn\\u00e9es d\\u00e9s\\u00e9quilibr\\u00e9es car il combine pr\\u00e9cision et rappel.\",\"image\":null,\"is_required\":true,\"created_at\":\"2026-07-27T20:42:30.000000Z\",\"updated_at\":\"2026-07-27T20:42:30.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(167, 'question', 'created', 'App\\Models\\Question', 'created', 26, NULL, NULL, '{\"attributes\":{\"id\":26,\"exam_id\":3,\"question_text\":\"Citez deux algorithmes de clustering.\",\"question_type\":\"single_choice\",\"points\":10,\"order_position\":8,\"explanation\":\"K-Means, DBSCAN, Clustering hi\\u00e9rarchique, et Gaussian Mixture Models sont des algorithmes de clustering courants.\",\"image\":null,\"is_required\":false,\"created_at\":\"2026-07-27T20:42:30.000000Z\",\"updated_at\":\"2026-07-27T20:42:30.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(168, 'question', 'created', 'App\\Models\\Question', 'created', 27, NULL, NULL, '{\"attributes\":{\"id\":27,\"exam_id\":3,\"question_text\":\"Quelle est la diff\\u00e9rence entre une variable cat\\u00e9gorielle et une variable continue ?\",\"question_type\":\"single_choice\",\"points\":10,\"order_position\":9,\"explanation\":\"Une variable cat\\u00e9gorielle prend des valeurs discr\\u00e8tes (ex: couleur), une variable continue peut prendre n\'importe quelle valeur dans un intervalle.\",\"image\":null,\"is_required\":true,\"created_at\":\"2026-07-27T20:42:30.000000Z\",\"updated_at\":\"2026-07-27T20:42:30.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(169, 'question', 'created', 'App\\Models\\Question', 'created', 28, NULL, NULL, '{\"attributes\":{\"id\":28,\"exam_id\":3,\"question_text\":\"Qu\'est-ce que le th\\u00e9or\\u00e8me de Bayes et \\u00e0 quoi sert-il en ML ?\",\"question_type\":\"single_choice\",\"points\":20,\"order_position\":10,\"explanation\":\"Le th\\u00e9or\\u00e8me de Bayes d\\u00e9crit la probabilit\\u00e9 conditionnelle. Il est utilis\\u00e9 dans les classifieurs na\\u00effs de Bayes pour la classification.\",\"image\":null,\"is_required\":true,\"created_at\":\"2026-07-27T20:42:30.000000Z\",\"updated_at\":\"2026-07-27T20:42:30.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
