(305, 'formation', 'created', 'App\\Models\\Formation', 'created', 12, NULL, NULL, '{\"attributes\":{\"id\":12,\"title\":\"Ma\\u00e7onnerie G\\u00e9n\\u00e9rale & Techniques de Construction\",\"slug\":\"maconnerie-generale-techniques-de-construction\",\"short_description\":\"Ma\\u00eetrisez les techniques fondamentales de la ma\\u00e7onnerie : fondations, \\u00e9l\\u00e9vation des murs, planchers et dallages.\",\"description\":\"Cette formation compl\\u00e8te vous forme aux gestes et techniques essentiels du m\\u00e9tier de ma\\u00e7on. Vous apprendrez \\u00e0 r\\u00e9aliser des fondations solides, \\u00e0 \\u00e9lever des murs en parpaings, briques et pierres, \\u00e0 couler des dallages et \\u00e0 poser des planchers.\",\"image\":null,\"price\":null,\"duration_hours\":80,\"difficulty_level\":\"beginner\",\"is_active\":false,\"is_featured\":true,\"is_certifying\":true,\"tags\":[\"ma\\u00e7onnerie\",\"fondations\",\"construction\",\"mur\",\"dallage\",\"BTP\"],\"created_at\":\"2026-07-27T20:42:31.000000Z\",\"updated_at\":\"2026-07-27T20:42:31.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:31', '2026-07-28 00:42:31'),
(306, 'section', 'created', 'App\\Models\\Section', 'created', 40, NULL, NULL, '{\"attributes\":{\"id\":40,\"formation_id\":12,\"title\":\"Fondations et Terrassement\",\"description\":\"Module 1 de la formation.\",\"order_position\":1,\"duration\":180,\"is_active\":true,\"created_at\":\"2026-07-27T20:42:31.000000Z\",\"updated_at\":\"2026-07-27T20:42:31.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:31', '2026-07-28 00:42:31'),
(307, 'section', 'created', 'App\\Models\\Section', 'created', 41, NULL, NULL, '{\"attributes\":{\"id\":41,\"formation_id\":12,\"title\":\"\\u00c9l\\u00e9vation des Murs\",\"description\":\"Module 2 de la formation.\",\"order_position\":2,\"duration\":240,\"is_active\":true,\"created_at\":\"2026-07-27T20:42:31.000000Z\",\"updated_at\":\"2026-07-27T20:42:31.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:31', '2026-07-28 00:42:31'),
