(375, 'formation', 'created', 'App\\Models\\Formation', 'created', 13, NULL, NULL, '{\"attributes\":{\"id\":13,\"title\":\"\\u00c9lectricit\\u00e9 B\\u00e2timent & Courants Faibles\",\"slug\":\"electricite-batiment-courants-faibles\",\"short_description\":\"Devenez \\u00e9lectricien qualifi\\u00e9 : installation r\\u00e9sidentielle, courants faibles et domotique.\",\"description\":\"Formation compl\\u00e8te aux m\\u00e9tiers de l\'\\u00e9lectricit\\u00e9 du b\\u00e2timent : fondamentaux, c\\u00e2blage r\\u00e9sidentiel et tertiaire, courants faibles (VDI, alarmes) et domotique. Conforme \\u00e0 la norme NF C 15-100.\",\"image\":null,\"price\":null,\"duration_hours\":75,\"difficulty_level\":\"beginner\",\"is_active\":false,\"is_featured\":true,\"is_certifying\":true,\"tags\":[\"\\u00e9lectricit\\u00e9\",\"courants faibles\",\"domotique\",\"NF C 15-100\",\"installation\",\"BTP\"],\"created_at\":\"2026-07-27T20:42:32.000000Z\",\"updated_at\":\"2026-07-27T20:42:32.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
