(430, 'exam', 'created', 'App\\Models\\Exam', 'created', 15, NULL, NULL, '{\"attributes\":{\"id\":15,\"examable_type\":\"App\\\\Models\\\\Formation\",\"examable_id\":13,\"title\":\"Examen final \\u2014 \\u00c9lectricit\\u00e9 B\\u00e2timent\",\"description\":\"\\u00c9valuation obligatoire pour valider cette \\u00e9tape.\",\"instructions\":\"R\\u00e9pondez \\u00e0 toutes les questions. L\'ordre change \\u00e0 chaque nouvelle tentative.\",\"duration_minutes\":20,\"passing_score\":75,\"max_attempts\":2,\"randomize_questions\":true,\"show_results_immediately\":true,\"is_active\":true,\"available_from\":\"2026-07-26 20:42:32\",\"available_until\":\"2028-07-27 20:42:32\",\"created_at\":\"2026-07-27T20:42:32.000000Z\",\"updated_at\":\"2026-07-27T20:42:32.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
