(445, 'formation', 'created', 'App\\Models\\Formation', 'created', 14, NULL, NULL, '{\"attributes\":{\"id\":14,\"title\":\"Plomberie & Installation Sanitaire\",\"slug\":\"plomberie-installation-sanitaire\",\"short_description\":\"R\\u00e9seaux d\'eau, d\'\\u00e9vacuation et pose d\'appareils sanitaires.\",\"description\":\"Formation compl\\u00e8te \\u00e0 la plomberie et au sanitaire : r\\u00e9seaux d\'alimentation (cuivre, PER, multicouche), \\u00e9vacuation et assainissement, pose et raccordement des appareils sanitaires. Conforme aux DTU applicables.\",\"image\":null,\"price\":null,\"duration_hours\":70,\"difficulty_level\":\"beginner\",\"is_active\":false,\"is_featured\":false,\"is_certifying\":true,\"tags\":[\"plomberie\",\"sanitaire\",\"chauffage\",\"eau\",\"\\u00e9vacuation\",\"BTP\"],\"created_at\":\"2026-07-27T20:42:32.000000Z\",\"updated_at\":\"2026-07-27T20:42:32.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(446, 'section', 'created', 'App\\Models\\Section', 'created', 46, NULL, NULL, '{\"attributes\":{\"id\":46,\"formation_id\":14,\"title\":\"R\\u00e9seau d\'Alimentation en Eau\",\"description\":\"Module 1 de la formation.\",\"order_position\":1,\"duration\":180,\"is_active\":true,\"created_at\":\"2026-07-27T20:42:32.000000Z\",\"updated_at\":\"2026-07-27T20:42:32.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
