(511, 'formation', 'created', 'App\\Models\\Formation', 'created', 15, NULL, NULL, '{\"attributes\":{\"id\":15,\"title\":\"Menuiserie & \\u00c9b\\u00e9nisterie\",\"slug\":\"menuiserie-ebenisterie\",\"short_description\":\"Travail du bois, assemblages, fabrication et pose de menuiseries.\",\"description\":\"Formation compl\\u00e8te aux m\\u00e9tiers du bois : essences, usinage et assemblage, fabrication de fen\\u00eatres, portes, escaliers et meubles sur mesure, finitions (vernis, cire, peinture).\",\"image\":null,\"price\":null,\"duration_hours\":90,\"difficulty_level\":\"intermediate\",\"is_active\":false,\"is_featured\":true,\"is_certifying\":true,\"tags\":[\"menuiserie\",\"\\u00e9b\\u00e9nisterie\",\"bois\",\"assemblage\",\"agencement\",\"BTP\"],\"created_at\":\"2026-07-27T20:42:32.000000Z\",\"updated_at\":\"2026-07-27T20:42:32.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
