(580, 'formation', 'created', 'App\\Models\\Formation', 'created', 16, NULL, NULL, '{\"attributes\":{\"id\":16,\"title\":\"Peinture & Finitions en B\\u00e2timent\",\"slug\":\"peinture-finitions-en-batiment\",\"short_description\":\"Pr\\u00e9paration des supports, techniques d\'application et finitions d\\u00e9coratives.\",\"description\":\"Formation aux techniques professionnelles de peinture : pr\\u00e9paration des supports, application peinture\\/papier peint, effets d\\u00e9coratifs (patine, stuc, b\\u00e9ton cir\\u00e9), finitions boiseries et sols.\",\"image\":null,\"price\":null,\"duration_hours\":60,\"difficulty_level\":\"beginner\",\"is_active\":false,\"is_featured\":false,\"is_certifying\":true,\"tags\":[\"peinture\",\"finition\",\"enduit\",\"d\\u00e9coration\",\"rev\\u00eatement\",\"BTP\"],\"created_at\":\"2026-07-27T20:42:33.000000Z\",\"updated_at\":\"2026-07-27T20:42:33.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
