(632, 'exam', 'created', 'App\\Models\\Exam', 'created', 27, NULL, NULL, '{\"attributes\":{\"id\":27,\"examable_type\":\"App\\\\Models\\\\Formation\",\"examable_id\":16,\"title\":\"Examen final \\u2014 Peinture et Finitions\",\"description\":\"\\u00c9valuation obligatoire pour valider cette \\u00e9tape.\",\"instructions\":\"R\\u00e9pondez \\u00e0 toutes les questions. L\'ordre change \\u00e0 chaque nouvelle tentative.\",\"duration_minutes\":20,\"passing_score\":75,\"max_attempts\":2,\"randomize_questions\":true,\"show_results_immediately\":true,\"is_active\":true,\"available_from\":\"2026-07-26 20:42:33\",\"available_until\":\"2028-07-27 20:42:33\",\"created_at\":\"2026-07-27T20:42:33.000000Z\",\"updated_at\":\"2026-07-27T20:42:33.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
