(647, 'formation', 'created', 'App\\Models\\Formation', 'created', 17, NULL, NULL, '{\"attributes\":{\"id\":17,\"title\":\"Soudure & M\\u00e9tallerie\",\"slug\":\"soudure-metallerie\",\"short_description\":\"Proc\\u00e9d\\u00e9s de soudage, m\\u00e9tallerie du b\\u00e2timent et ferronnerie.\",\"description\":\"Formation aux techniques de soudage (arc, MIG\\/MAG, TIG, oxycoupage) et \\u00e0 la m\\u00e9tallerie : portails, garde-corps, charpentes m\\u00e9talliques et ferronnerie d\\u00e9corative.\",\"image\":null,\"price\":null,\"duration_hours\":85,\"difficulty_level\":\"intermediate\",\"is_active\":false,\"is_featured\":false,\"is_certifying\":true,\"tags\":[\"soudure\",\"m\\u00e9tallerie\",\"ferronnerie\",\"soudage\",\"MIG\",\"TIG\",\"BTP\"],\"created_at\":\"2026-07-27T20:42:33.000000Z\",\"updated_at\":\"2026-07-27T20:42:33.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(648, 'section', 'created', 'App\\Models\\Section', 'created', 55, NULL, NULL, '{\"attributes\":{\"id\":55,\"formation_id\":17,\"title\":\"Fondamentaux de la Soudure\",\"description\":\"Module 1 de la formation.\",\"order_position\":1,\"duration\":150,\"is_active\":true,\"created_at\":\"2026-07-27T20:42:33.000000Z\",\"updated_at\":\"2026-07-27T20:42:33.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
