(782, 'formation', 'created', 'App\\Models\\Formation', 'created', 19, NULL, NULL, '{\"attributes\":{\"id\":19,\"title\":\"Gestion de Chantier & S\\u00e9curit\\u00e9 BTP\",\"slug\":\"gestion-de-chantier-securite-btp\",\"short_description\":\"Planification, conduite de travaux, s\\u00e9curit\\u00e9 et pr\\u00e9vention.\",\"description\":\"Formation \\u00e0 la gestion de chantier et \\u00e0 la s\\u00e9curit\\u00e9 BTP : organisation et planification, direction des \\u00e9quipes, suivi budg\\u00e9taire, r\\u00e9glementation s\\u00e9curit\\u00e9 (PPSPS, DUERP), \\u00e9valuation des risques, EPI\\/EPC.\",\"image\":null,\"price\":null,\"duration_hours\":70,\"difficulty_level\":\"intermediate\",\"is_active\":false,\"is_featured\":true,\"is_certifying\":true,\"tags\":[\"gestion chantier\",\"s\\u00e9curit\\u00e9\",\"BTP\",\"conduite travaux\",\"pr\\u00e9vention\",\"planification\"],\"created_at\":\"2026-07-27T20:42:34.000000Z\",\"updated_at\":\"2026-07-27T20:42:34.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
(783, 'section', 'created', 'App\\Models\\Section', 'created', 61, NULL, NULL, '{\"attributes\":{\"id\":61,\"formation_id\":19,\"title\":\"Organisation et Planification\",\"description\":\"Module 1 de la formation.\",\"order_position\":1,\"duration\":150,\"is_active\":true,\"created_at\":\"2026-07-27T20:42:34.000000Z\",\"updated_at\":\"2026-07-27T20:42:34.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
