(785, 'section', 'created', 'App\\Models\\Section', 'created', 63, NULL, NULL, '{\"attributes\":{\"id\":63,\"formation_id\":19,\"title\":\"S\\u00e9curit\\u00e9 et Pr\\u00e9vention\",\"description\":\"Module 3 de la formation.\",\"order_position\":3,\"duration\":180,\"is_active\":true,\"created_at\":\"2026-07-27T20:42:34.000000Z\",\"updated_at\":\"2026-07-27T20:42:34.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
(786, 'chapter', 'created', 'App\\Models\\Chapter', 'created', 138, NULL, NULL, '{\"attributes\":{\"id\":138,\"section_id\":61,\"title\":\"\\u00c9tude de faisabilit\\u00e9\",\"content\":\"# Faisabilit\\u00e9\\n\\n## Analyse\\n- Site : acc\\u00e8s, r\\u00e9seaux, nuisances.\\n- Plans : architecte, structure, CVC, \\u00e9lectricit\\u00e9.\\n- D\\u00e9lais : planning pr\\u00e9visionnel.\\n- Budget : estimation co\\u00fbts.\\n\\n## Dossier technique\\n- DCE, CCTP, BPU, DPGF.\\n- Notes de calcul, plans d\'ex\\u00e9cution.\\n- DOE en fin de chantier.\\n\\n## Autorisations\\n- Permis de construire.\\n- D\\u00e9claration pr\\u00e9alable.\\n- Autorisations voirie.\",\"content_type\":\"text\",\"media_url\":null,\"video_url\":null,\"cover_image\":null,\"markdown_file\":null,\"processing_status\":null,\"processing_error\":null,\"processing_metadata\":null,\"processing_started_at\":null,\"processed_at\":null,\"duration_minutes\":35,\"order_position\":1,\"is_free\":true,\"is_active\":true,\"description\":\"Pr\\u00e9parer le projet avant l\'ouverture du chantier.\",\"created_at\":\"2026-07-27T20:42:34.000000Z\",\"updated_at\":\"2026-07-27T20:42:34.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
(787, 'chapter', 'created', 'App\\Models\\Chapter', 'created', 139, NULL, NULL, '{\"attributes\":{\"id\":139,\"section_id\":61,\"title\":\"Planification de chantier\",\"content\":\"# Planification\\n\\n## Gantt\\n- T\\u00e2ches en barres horizontales.\\n- Dur\\u00e9e, ant\\u00e9riorit\\u00e9s, jalons.\\n\\n## PERT\\n- R\\u00e9seau logique des t\\u00e2ches.\\n- Chemin critique = dur\\u00e9e minimale.\\n\\n## Logiciels\\n- MS Project, Primavera.\\n- GanttProject, OpenProject.\\n\\n## Phases\\n1. Installation de chantier.\\n2. Terrassement\\/fondations.\\n3. Structure.\\n4. Second oeuvre.\\n5. Finitions.\\n6. R\\u00e9ception.\",\"content_type\":\"text\",\"media_url\":null,\"video_url\":null,\"cover_image\":null,\"markdown_file\":null,\"processing_status\":null,\"processing_error\":null,\"processing_metadata\":null,\"processing_started_at\":null,\"processed_at\":null,\"duration_minutes\":35,\"order_position\":2,\"is_free\":false,\"is_active\":true,\"description\":\"Gantt, PERT et chemin critique.\",\"created_at\":\"2026-07-27T20:42:34.000000Z\",\"updated_at\":\"2026-07-27T20:42:34.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:34', '2026-07-28 00:42:34');
INSERT INTO `activity_log` (`id`, `log_name`, `description`, `subject_type`, `event`, `subject_id`, `causer_type`, `causer_id`, `properties`, `batch_uuid`, `created_at`, `updated_at`) VALUES
(788, 'chapter', 'created', 'App\\Models\\Chapter', 'created', 140, NULL, NULL, '{\"attributes\":{\"id\":140,\"section_id\":61,\"title\":\"Gestion des approvisionnements\",\"content\":\"# Approvisionnements\\n\\n## Plan\\n- D\\u00e9fini \\u00e0 partir du planning.\\n- D\\u00e9lais : b\\u00e9ton 48 h, armatures 1 sem, menuiseries 4\\u20136 sem.\\n\\n## Stockage\\n- Zone stable, drain\\u00e9e, s\\u00e9curis\\u00e9e.\\n- Couvert (ciment, pl\\u00e2tre, bois).\\n- Rotation FIFO.\\n\\n## R\\u00e9ception\\n- V\\u00e9rification quantitative et qualitative.\\n- R\\u00e9serves sur bon de livraison.\\n- Photo des anomalies.\\n\\n## Suivi\\n- Tableau consommations.\\n- D\\u00e9tection \\u00e9carts (vol, perte, surconsommation).\",\"content_type\":\"text\",\"media_url\":null,\"video_url\":null,\"cover_image\":null,\"markdown_file\":null,\"processing_status\":null,\"processing_error\":null,\"processing_metadata\":null,\"processing_started_at\":null,\"processed_at\":null,\"duration_minutes\":30,\"order_position\":3,\"is_free\":false,\"is_active\":true,\"description\":\"Logistique et suivi des mat\\u00e9riaux.\",\"created_at\":\"2026-07-27T20:42:34.000000Z\",\"updated_at\":\"2026-07-27T20:42:34.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
(789, 'chapter', 'created', 'App\\Models\\Chapter', 'created', 141, NULL, NULL, '{\"attributes\":{\"id\":141,\"section_id\":62,\"title\":\"Direction et coordination\",\"content\":\"# Direction des \\u00e9quipes\\n\\n## R\\u00f4les\\n- Chef de chantier : ex\\u00e9cution terrain.\\n- Conducteur de travaux : gestion technique\\/financi\\u00e8re.\\n- Compagnons : ex\\u00e9cution.\\n\\n## Communication\\n- R\\u00e9union hebdomadaire.\\n- Ordre de service (modifications).\\n- Main courante (journal quotidien).\\n\\n## Sous-traitance\\n- S\\u00e9lection : r\\u00e9f\\u00e9rences, capacit\\u00e9.\\n- Contrat : prestations, d\\u00e9lais, p\\u00e9nalit\\u00e9s.\\n- Coordination interfaces.\\n\\n## Conflits\\n- M\\u00e9diation active.\\n- R\\u00e9union de crise.\\n- Signalement hi\\u00e9rarchique.\",\"content_type\":\"text\",\"media_url\":null,\"video_url\":null,\"cover_image\":null,\"markdown_file\":null,\"processing_status\":null,\"processing_error\":null,\"processing_metadata\":null,\"processing_started_at\":null,\"processed_at\":null,\"duration_minutes\":30,\"order_position\":1,\"is_free\":false,\"is_active\":true,\"description\":\"Animer les \\u00e9quipes et sous-traitants.\",\"created_at\":\"2026-07-27T20:42:34.000000Z\",\"updated_at\":\"2026-07-27T20:42:34.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
(790, 'chapter', 'created', 'App\\Models\\Chapter', 'created', 142, NULL, NULL, '{\"attributes\":{\"id\":142,\"section_id\":62,\"title\":\"Suivi budg\\u00e9taire\",\"content\":\"# Suivi budg\\u00e9taire\\n\\n## Budget pr\\u00e9visionnel\\n- D\\u00e9compte mensuel (quantit\\u00e9s \\u00d7 PU).\\n- Variation co\\u00fbts par lot.\\n- R\\u00e9vision de prix (indice BT).\\n\\n## Postes\\n| Poste | Poids |\\n|---|---|\\n| Main-d\'oeuvre | 30\\u201340 % |\\n| Mat\\u00e9riaux | 25\\u201335 % |\\n| Sous-traitance | 15\\u201325 % |\\n| Location | 5\\u201310 % |\\n| Frais g\\u00e9n\\u00e9raux | 5\\u201310 % |\\n\\n## R\\u00e9unions\\n- Avancement, points bloquants.\\n- Validation situations.\\n- Planning actualis\\u00e9.\",\"content_type\":\"text\",\"media_url\":null,\"video_url\":null,\"cover_image\":null,\"markdown_file\":null,\"processing_status\":null,\"processing_error\":null,\"processing_metadata\":null,\"processing_started_at\":null,\"processed_at\":null,\"duration_minutes\":35,\"order_position\":2,\"is_free\":false,\"is_active\":true,\"description\":\"Ma\\u00eetriser le budget chantier.\",\"created_at\":\"2026-07-27T20:42:34.000000Z\",\"updated_at\":\"2026-07-27T20:42:34.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
(791, 'chapter', 'created', 'App\\Models\\Chapter', 'created', 143, NULL, NULL, '{\"attributes\":{\"id\":143,\"section_id\":62,\"title\":\"R\\u00e9unions et reporting\",\"content\":\"# R\\u00e9unions\\n\\n## Types\\n- Kick-off : pr\\u00e9sentation projet.\\n- Hebdomadaire : suivi + s\\u00e9curit\\u00e9.\\n- Coordination : interfaces techniques.\\n- Cl\\u00f4ture : bilan et r\\u00e9ception.\\n\\n## Ordre du jour\\n1. D\\u00e9cisions pr\\u00e9c\\u00e9dentes.\\n2. Avancement par lot.\\n3. S\\u00e9curit\\u00e9\\/incidents.\\n4. Planning.\\n5. Modifications\\/avenants.\\n6. Questions diverses.\\n\\n## CR\\n- Diffus\\u00e9 sous 48 h.\\n- Tableau : Action, Responsable, Date.\",\"content_type\":\"text\",\"media_url\":null,\"video_url\":null,\"cover_image\":null,\"markdown_file\":null,\"processing_status\":null,\"processing_error\":null,\"processing_metadata\":null,\"processing_started_at\":null,\"processed_at\":null,\"duration_minutes\":25,\"order_position\":3,\"is_free\":false,\"is_active\":true,\"description\":\"Comptes-rendus efficaces.\",\"created_at\":\"2026-07-27T20:42:34.000000Z\",\"updated_at\":\"2026-07-27T20:42:34.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
(792, 'chapter', 'created', 'App\\Models\\Chapter', 'created', 144, NULL, NULL, '{\"attributes\":{\"id\":144,\"section_id\":63,\"title\":\"R\\u00e9glementation s\\u00e9curit\\u00e9\",\"content\":\"# R\\u00e9glementation\\n\\n## Textes\\n- Code du travail L. 4121-1 \\u00e0 5.\\n- D\\u00e9cret 2008-244.\\n- R. 4534-1 (BTP).\\n\\n## Documents\\n- **PPSPS** : par entreprise.\\n- **PGCSPS** : plusieurs entreprises.\\n- Registre s\\u00e9curit\\u00e9 : accidents, incidents.\\n- Registre v\\u00e9rification EPI\\/\\u00e9chafaudages.\\n- **DUERP** : document unique.\\n\\n## Acteurs\\n- Coordonnateur SPS (> 5000 h\\u00b7j).\\n- CARSAT, OPPBTP, Inspection travail.\\n\\n## Sanctions\\n- Absence PPSPS : amende \\u2264 10 000 \\u20ac.\\n- Absence DUERP : amende \\u2264 1 500 \\u20ac.\",\"content_type\":\"text\",\"media_url\":null,\"video_url\":null,\"cover_image\":null,\"markdown_file\":null,\"processing_status\":null,\"processing_error\":null,\"processing_metadata\":null,\"processing_started_at\":null,\"processed_at\":null,\"duration_minutes\":35,\"order_position\":1,\"is_free\":false,\"is_active\":true,\"description\":\"PPSPS, registre, plan de pr\\u00e9vention.\",\"created_at\":\"2026-07-27T20:42:34.000000Z\",\"updated_at\":\"2026-07-27T20:42:34.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
(793, 'chapter', 'created', 'App\\Models\\Chapter', 'created', 145, NULL, NULL, '{\"attributes\":{\"id\":145,\"section_id\":63,\"title\":\"\\u00c9valuation des risques\",\"content\":\"# \\u00c9valuation des risques\\n\\n## D\\u00e9marche\\n1. Identifier les dangers.\\n2. Analyser : gravit\\u00e9 \\u00d7 probabilit\\u00e9 \\u00d7 exposition.\\n3. Hi\\u00e9rarchiser.\\n4. Planifier actions.\\n5. Suivre et r\\u00e9\\u00e9valuer.\\n\\n## Risques BTP\\n| Risque | Gravit\\u00e9 | Fr\\u00e9quence |\\n|---|---|---|\\n| Chute hauteur | Tr\\u00e8s \\u00e9lev\\u00e9e | Tr\\u00e8s fr\\u00e9quente |\\n| \\u00c9lectrocution | \\u00c9lev\\u00e9e | Rare |\\n| \\u00c9crasement | \\u00c9lev\\u00e9e | Peu fr\\u00e9quente |\\n| Manutention | Moyenne | Tr\\u00e8s fr\\u00e9quente |\\n| Silice | \\u00c9lev\\u00e9e (LT) | Quotidienne |\\n\\n## Cotation\\nCriticit\\u00e9 = Gravit\\u00e9 \\u00d7 Probabilit\\u00e9 (seuil \\u2265 8\\/16).\",\"content_type\":\"text\",\"media_url\":null,\"video_url\":null,\"cover_image\":null,\"markdown_file\":null,\"processing_status\":null,\"processing_error\":null,\"processing_metadata\":null,\"processing_started_at\":null,\"processed_at\":null,\"duration_minutes\":30,\"order_position\":2,\"is_free\":false,\"is_active\":true,\"description\":\"Identifier et hi\\u00e9rarchiser les risques.\",\"created_at\":\"2026-07-27T20:42:34.000000Z\",\"updated_at\":\"2026-07-27T20:42:34.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
(794, 'chapter', 'created', 'App\\Models\\Chapter', 'created', 146, NULL, NULL, '{\"attributes\":{\"id\":146,\"section_id\":63,\"title\":\"\\u00c9quipements de protection\",\"content\":\"# \\u00c9quipements de protection\\n\\n## EPC (collective)\\n- Garde-corps : \\u2265 100 cm, lisse 45 cm, plinthe.\\n- Filets s\\u00e9curit\\u00e9 : mailles \\u2264 10 cm.\\n- \\u00c9chafaudages : montage par personnel qualifi\\u00e9.\\n\\n## EPI (individuelle)\\n- Casque (norme EN 397).\\n- Chaussures s\\u00e9curit\\u00e9 (EN 345).\\n- Harnais anti-chute (EN 361).\\n- Gants, lunettes, protections auditives.\\n\\n## Principes\\n- EPC prioritaire sur EPI.\\n- V\\u00e9rification p\\u00e9riodique obligatoire.\\n- Formation des utilisateurs.\",\"content_type\":\"text\",\"media_url\":null,\"video_url\":null,\"cover_image\":null,\"markdown_file\":null,\"processing_status\":null,\"processing_error\":null,\"processing_metadata\":null,\"processing_started_at\":null,\"processed_at\":null,\"duration_minutes\":30,\"order_position\":3,\"is_free\":false,\"is_active\":true,\"description\":\"EPC et EPI sur le chantier.\",\"created_at\":\"2026-07-27T20:42:34.000000Z\",\"updated_at\":\"2026-07-27T20:42:34.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
