(852, 'formation', 'created', 'App\\Models\\Formation', 'created', 20, NULL, NULL, '{\"attributes\":{\"id\":20,\"title\":\"Intelligence Artificielle, Agents Autonomes & Protocole MCP\",\"slug\":\"ia-agents-autonomes-protocole-mcp\",\"short_description\":\"Ma\\u00eetrisez les fondamentaux de l\'IA g\\u00e9n\\u00e9rative, concevez des agents autonomes et impl\\u00e9mentez des serveurs MCP avec Laravel.\",\"description\":\"## Objectifs de la formation\\n\\nComprendre et ma\\u00eetriser l\'\\u00e9cosyst\\u00e8me moderne de l\'intelligence artificielle :\\n\\n- **Fondamentaux des LLMs** \\u2014 Architecture Transformer, tokenisation, m\\u00e9canismes d\'attention.\\n- **RAG et embeddings** \\u2014 Recherche s\\u00e9mantique, vectorisation et augmentation contextuelle.\\n- **Agents autonomes** \\u2014 Conception d\'agents avec outils, m\\u00e9moire et planification.\\n- **Model Context Protocol (MCP)** \\u2014 Cr\\u00e9ation de serveurs MCP avec Laravel, exposition d\'outils et de ressources.\\n- **D\\u00e9ploiement s\\u00e9curis\\u00e9** \\u2014 Authentification, rate limiting, monitoring et int\\u00e9gration avec les clients MCP.\\n\\n\\u00c0 l\'issue de cette formation, vous serez capable de d\\u00e9velopper des solutions IA compl\\u00e8tes, des chatbots RAG aux serveurs MCP interop\\u00e9rables.\",\"image\":null,\"price\":\"0.00\",\"duration_hours\":60,\"difficulty_level\":\"intermediate\",\"is_active\":true,\"is_featured\":false,\"is_certifying\":true,\"tags\":[\"IA\",\"Intelligence Artificielle\",\"MCP\",\"Agents\",\"LLM\",\"Laravel\",\"RAG\",\"Automatisation\"],\"created_at\":\"2026-07-27T20:42:34.000000Z\",\"updated_at\":\"2026-07-27T20:42:34.000000Z\"},\"ip_address\":\"127.0.0.1\",\"user_agent\":\"Symfony\",\"url\":\"https:\\/\\/formations.btpcma.org\"}', NULL, '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
