INSERT INTO `chapters` (`id`, `section_id`, `title`, `content`, `content_type`, `media_url`, `video_url`, `cover_image`, `markdown_file`, `processing_status`, `processing_error`, `processing_metadata`, `processing_started_at`, `processed_at`, `duration_minutes`, `order_position`, `is_free`, `is_active`, `description`, `created_at`, `updated_at`) VALUES
(1, 1, 'Introduction à HTML5', 'HTML5 est le langage standard pour créer des pages web. Dans ce chapitre, nous allons voir les balises essentielles : structure de base, titres, paragraphes, listes, liens et images. Vous apprendrez à organiser votre contenu avec des balises sémantiques comme header, nav, main, section, article et footer.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 45, 1, 1, 1, 'Découvrez les bases du langage HTML5.', '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(2, 1, 'CSS3 - Mise en page et design', 'Le CSS3 permet de donner du style à vos pages HTML. Nous aborderons les sélecteurs, le modèle de boîte, le flexbox, le grid, les animations et les media queries pour le responsive design. Vous serez capable de créer des mises en page modernes et adaptatives.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 2, 0, 1, 'Apprenez à styliser vos pages web avec CSS3.', '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(3, 1, 'JavaScript - Les Fondamentaux', 'JavaScript est le langage de programmation du web. Ce chapitre couvre les variables, les types de données, les fonctions, les objets, les tableaux, les boucles et les conditions. Vous apprendrez à manipuler le DOM et à gérer les événements utilisateur.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 90, 3, 0, 1, 'Les bases de la programmation JavaScript.', '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(4, 2, 'Introduction à PHP 8', 'PHP 8 apporte des améliorations significatives. Nous verrons la syntaxe moderne, les types stricts, les attributs, les enumérations, et les fonctionnalités orientées objet. Vous comprendrez comment PHP fonctionne côté serveur.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 1, 0, 1, 'Les bases de PHP moderne.', '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(5, 2, 'Laravel - Routing & Controllers', 'Laravel est le framework PHP le plus populaire. Ce chapitre vous montre comment configurer les routes, créer des contrôleurs, gérer les requêtes et les réponses, et utiliser les middlewares. Vous construirez votre première API REST.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 90, 2, 0, 1, 'Les bases du framework Laravel.', '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(6, 2, 'Eloquent ORM & Migrations', 'Eloquent est l\'ORM de Laravel. Vous apprendrez à créer des migrations, des modèles, des relations (belongsTo, hasMany, belongsToMany), et à effectuer des requêtes avancées. La gestion des bases de données n\'aura plus de secrets pour vous.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 75, 3, 0, 1, 'La couche base de données de Laravel.', '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(7, 3, 'Introduction à React', 'React est la bibliothèque JavaScript la plus utilisée pour les interfaces utilisateur. Nous verrons les composants, le JSX, les props, le state, et le cycle de vie. Vous comprendrez l\'approche déclarative de React.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 1, 0, 1, 'Les concepts fondamentaux de React.', '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(8, 3, 'Hooks & Gestion d\'état', 'Les hooks (useState, useEffect, useContext, useReducer) sont au cœur de React moderne. Vous apprendrez à gérer l\'état local, les effets de bord, le contexte global, et à optimiser les performances avec useMemo et useCallback.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 90, 2, 0, 1, 'Les hooks React pour une gestion d\'état avancée.', '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(9, 3, 'Tailwind CSS - Design System', 'Tailwind CSS est un framework utility-first qui accélère le développement. Vous maîtriserez les classes utilitaires, la personnalisation du thème, le responsive design, le dark mode, et la création de composants réutilisables.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 3, 0, 1, 'Créez des designs professionnels avec Tailwind CSS.', '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(10, 4, 'Déploiement avec Laravel Forge', 'Laravel Forge simplifie le déploiement. Vous apprendrez à configurer un serveur VPS, à déployer votre application, à gérer les tâches cron, les queues, et à configurer SSL. Votre site sera prêt pour la production.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 45, 1, 0, 1, 'Mettez votre application en production.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(11, 4, 'CI/CD avec GitHub Actions', 'L\'intégration et le déploiement continus sont essentiels. Ce chapitre vous montre comment configurer GitHub Actions pour exécuter vos tests, analyser votre code, et déployer automatiquement sur votre serveur à chaque push.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 2, 0, 1, 'Automatisez vos déploiements.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(12, 5, 'L\'écosystème du Marketing Digital', 'Le marketing digital englobe toutes les stratégies de promotion sur internet. Nous verrons les différents canaux : SEO, SEA, social media, email marketing, et comment ils s\'articulent dans une stratégie globale. Vous découvrirez les KPI essentiels à suivre.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 45, 1, 1, 1, 'Comprendre le paysage du marketing en ligne.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(13, 5, 'Stratégie de Contenu', 'Le content marketing est au cœur du marketing digital. Apprenez à définir votre ligne éditoriale, à créer un calendrier de contenu, à produire des articles de blog, des vidéos et des infographies qui engagent votre audience.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 2, 0, 1, 'Créez une stratégie de contenu efficace.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(14, 6, 'SEO Technique', 'Le SEO technique est la base du référencement. Nous couvrons l\'architecture du site, les balises meta, le balisage schema.org, la vitesse de chargement, le mobile-first, les sitemaps et le fichier robots.txt. Un site bien structuré est la clé du succès.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 75, 1, 0, 1, 'Optimisez la technique de votre site.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(15, 6, 'SEO On-Page & Off-Page', 'Le SEO on-page concerne l\'optimisation du contenu : mots-clés, balises title, meta descriptions, structure Hn, maillage interne. Le SEO off-page traite du netlinking, des backlinks, et de l\'autorité de domaine. Une stratégie complète pour grimper dans les SERP.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 2, 0, 1, 'Optimisez votre contenu et votre autorité.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(16, 7, 'Google Ads - Campagnes Search', 'Google Ads est la plateforme publicitaire la plus puissante. Ce chapitre vous montre comment configurer des campagnes Search, choisir les mots-clés, rédiger des annonces percutantes, définir un budget, et analyser les performances.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 90, 1, 0, 1, 'Créez des campagnes Google Ads performantes.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(17, 7, 'Social Ads - Facebook & Instagram', 'Facebook Ads et Instagram Ads offrent un ciblage précis. Vous apprendrez à créer des audiences, à concevoir des visuels accrocheurs, à configurer des campagnes de conversion, et à optimiser votre ROI avec le pixel Facebook.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 2, 0, 1, 'Publicité sur les réseaux sociaux.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(18, 8, 'Stratégie LinkedIn & Twitter', 'LinkedIn est le réseau professionnel par excellence. Apprenez à optimiser votre profil, à créer du contenu engageant, à développer votre réseau, et à utiliser LinkedIn pour le B2B. Twitter/X pour la veille et l\'engagement communautaire.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 45, 1, 0, 1, 'Développez votre marque personnelle.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(19, 8, 'TikTok & Instagram Reels', 'La vidéo courte est le format roi. Découvrez comment créer du contenu viral sur TikTok et Instagram Reels, utiliser les tendances, optimiser votre stratégie hashtag, et monétiser votre audience.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 2, 0, 1, 'Maîtrisez le marketing vidéo court.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(20, 9, 'Python - Les bases', 'Python est le langage incontournable de la data science. Nous couvrons la syntaxe de base, les types de données, les structures de contrôle, les fonctions, les compréhensions de liste, et la manipulation de fichiers. Même les débutants pourront suivre.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 90, 1, 1, 1, 'Les fondamentaux de Python pour la data science.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(21, 9, 'Introduction à Jupyter Notebook', 'Jupyter Notebook est l\'environnement de travail des data scientists. Vous apprendrez à installer et configurer Jupyter, à créer des notebooks, à combiner code et documentation, et à visualiser vos résultats directement dans le notebook.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 2, 0, 1, 'L\'outil essentiel pour la data science.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(22, 10, 'NumPy - Calculs Numériques', 'NumPy est la bibliothèque fondamentale pour le calcul scientifique en Python. Nous explorerons les tableaux multidimensionnels, les opérations vectorisées, les fonctions mathématiques, l\'algèbre linéaire, et la génération de nombres aléatoires.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 90, 1, 0, 1, 'Les tableaux et opérations numériques avec NumPy.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(23, 10, 'Pandas - Analyse de données', 'Pandas est l\'outil incontournable pour l\'analyse de données. Vous maîtriserez les DataFrames et Series, le nettoyage des données, le filtrage, le regroupement, les jointures, et l\'import/export depuis CSV, Excel, JSON et SQL.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 120, 2, 0, 1, 'Manipulez et analysez des données tabulaires.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(24, 11, 'Matplotlib - Graphiques fondamentaux', 'Matplotlib est la bibliothèque de visualisation la plus ancienne et la plus flexible. Vous apprendrez à créer des graphiques en lignes, barres, secteurs, histogrammes, boîtes à moustaches, et à personnaliser chaque aspect de vos figures.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 1, 0, 1, 'Créez des graphiques professionnels.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(25, 11, 'Seaborn - Visualisations statistiques', 'Seaborn simplifie la création de graphiques statistiques. Nous verrons les heatmaps, les pairplots, les boxplots, les violin plots, et comment visualiser les distributions et les relations entre variables.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 45, 2, 0, 1, 'Des graphiques statistiques élégants.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(26, 12, 'Apprentissage Supervisé', 'L\'apprentissage supervisé est au cœur du machine learning. Nous couvrons la régression linéaire, la régression logistique, les arbres de décision, les forêts aléatoires, les SVM, et les k-plus proches voisins. Chaque algorithme est implémenté avec Scikit-learn.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 120, 1, 0, 1, 'Les algorithmes de classification et régression.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(27, 12, 'Apprentissage Non Supervisé', 'L\'apprentissage non supervisé permet d\'explorer des données sans étiquettes. Nous étudierons le K-Means, le clustering hiérarchique, le DBSCAN, l\'ACP (analyse en composantes principales), et le t-SNE pour visualiser des données complexes.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 90, 2, 0, 1, 'Découvrez le clustering et la réduction de dimension.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(28, 12, 'Évaluation & Optimisation des modèles', 'Un bon modèle doit être évalué correctement. Nous verrons les métriques de performance (accuracy, precision, recall, F1, AUC), la validation croisée, la recherche d\'hyperparamètres avec GridSearchCV, et les techniques pour éviter le surapprentissage.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 3, 0, 1, 'Validez et améliorez vos modèles de ML.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(29, 13, 'Introduction à la Cybersécurité', 'La cybersécurité est l\'ensemble des pratiques visant à protéger les systèmes informatiques contre les attaques. Ce chapitre couvre les types de menaces (malwares, phishing, DDoS), les principes de sécurité (CIA : Confidentialité, Intégrité, Disponibilité), et le paysage actuel des cyberattaques.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 45, 1, 1, 1, 'Les concepts clés de la sécurité informatique.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(30, 13, 'Cryptographie & Chiffrement', 'La cryptographie est essentielle à la sécurité moderne. Vous découvrirez le chiffrement symétrique et asymétrique, les fonctions de hachage, les certificats SSL/TLS, et la signature électronique. Des exemples pratiques avec OpenSSL et GPG.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 2, 0, 1, 'Les bases du chiffrement et de la cryptographie.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(31, 14, 'Méthodologie du Pentest', 'Un pentest suit une méthodologie stricte : reconnaissance, scanning, exploitation, post-exploitation et reporting. Vous apprendrez à utiliser Kali Linux, Nmap, Metasploit et à structurer vos tests avec la norme PTES (Penetration Testing Execution Standard).', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 90, 1, 0, 1, 'Les phases d\'un test d\'intrusion professionnel.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(32, 14, 'Exploitation de Vulnérabilités', 'Mettez en pratique vos connaissances avec des exercices sur des systèmes vulnérables. Vous utiliserez Burp Suite pour les tests web, Metasploit pour l\'exploitation, et analyserez des vulnérabilités courantes : injections SQL, XSS, CSRF, et buffer overflows.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 120, 2, 0, 1, 'Identifiez et exploitez les failles de sécurité.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(33, 15, 'Architecture Réseau Sécurisée', 'Une architecture réseau sécurisée repose sur le cloisonnement, les VLANs, les DMZ, et les pare-feux. Vous apprendrez à configurer des règles de filtrage, à sécuriser les accès distants avec VPN, et à mettre en place la détection d\'intrusion avec Snort et Suricata.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 75, 1, 0, 1, 'Concevez des réseaux résistants aux attaques.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(34, 15, 'Analyse de Trafic & Forensique', 'Wireshark est l\'outil indispensable pour l\'analyse de trafic réseau. Vous apprendrez à capturer et filtrer le trafic, à identifier des comportements suspects, et à mener une investigation forensique post-incident. Des scénarios réels d\'attaques réseaux seront analysés.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 2, 0, 1, 'Analysez le trafic réseau et enquêtez sur les incidents.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(35, 16, 'OWASP Top 10', 'L\'OWASP Top 10 est la référence des vulnérabilités web. Nous détaillons chaque catégorie : injections, XSS, broken authentication, sensitive data exposure, XXE, broken access control, etc. Pour chaque faille, vous verrez comment l\'identifier et la corriger.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 90, 1, 0, 1, 'Les 10 vulnérabilités web les plus critiques.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(36, 16, 'Sécurisation d\'une Application Laravel', 'Laravel intègre de nombreuses protections de série. Ce chapitre montre comment sécuriser une application Laravel : protection CSRF, validation des entrées, échappement des sorties, authentification robuste, rate limiting, et durcissement de la configuration serveur.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 2, 0, 1, 'Protégez votre application Laravel contre les attaques.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(37, 17, 'Concepts du Cloud Computing', 'Le cloud computing transforme la façon dont les applications sont déployées et gérées. Ce chapitre explique les modèles de service (IaaS, PaaS, SaaS), les modèles de déploiement (public, privé, hybride), et les avantages du cloud : scalabilité, élasticité, et paiement à l\'usage.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 45, 1, 1, 1, 'Les fondamentaux du cloud : IaaS, PaaS, SaaS.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(38, 17, 'AWS - Services Essentiels', 'Amazon Web Services est le leader du cloud. Vous découvrirez EC2 (machines virtuelles), S3 (stockage objet), RDS (bases de données gérées), Lambda (serverless), et IAM (gestion des identités et accès). Des exercices pratiques pour chaque service.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 90, 2, 0, 1, 'Découvrez les services clés d\'AWS.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(39, 18, 'Docker - Prise en main', 'Docker révolutionne le déploiement des applications. Vous apprendrez à créer des images avec des Dockerfiles, à gérer les conteneurs, les volumes, les réseaux, et à utiliser Docker Compose pour des applications multi-conteneurs. Des exemples concrets avec Laravel et PostgreSQL.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 75, 1, 0, 1, 'Les bases de Docker et des conteneurs.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(40, 18, 'Docker en Production', 'Passer Docker en production demande des bonnes pratiques : images multistage, sécurité des conteneurs, gestion des secrets, logging centralisé, monitoring avec Prometheus, et orchestration des déploiements blue/green.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 2, 0, 1, 'Bonnes pratiques et optimisation des conteneurs.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(41, 19, 'Kubernetes - Concepts Fondamentaux', 'Kubernetes est la plateforme d\'orchestration de conteneurs la plus populaire. Ce chapitre couvre les pods, les deployments, les services, les namespaces, et les configmaps. Vous déploierez votre première application sur un cluster Kubernetes avec Minikube.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 90, 1, 0, 1, 'L\'essentiel de Kubernetes pour orchestrer vos conteneurs.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(42, 19, 'Kubernetes Avancé', 'Approfondissez Kubernetes avec les Ingress controllers, le gestionnaire de paquets Helm, les volumes persistants, les StatefulSets, et le auto-scaling (HPA). Vous apprendrez à gérer des applications d\'état et à automatiser les déploiements sur le cloud.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 90, 2, 0, 1, 'Ingress, Helm, et gestion des stocks.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(43, 20, 'Pipelines CI/CD avec GitHub Actions', 'GitHub Actions permet de créer des pipelines CI/CD directement depuis votre dépôt. Vous configurerez des workflows pour exécuter les tests, analyser la qualité du code, builder les images Docker, et déployer automatiquement sur AWS ou DigitalOcean.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 75, 1, 0, 1, 'Automatisez vos tests et déploiements.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(44, 20, 'Terraform & Infrastructure as Code', 'Terraform permet de décrire votre infrastructure sous forme de code (IaC). Vous apprendrez à écrire des configurations Terraform pour provisionner des ressources AWS (EC2, RDS, VPC), à gérer l\'état distant, et à intégrer Terraform dans vos pipelines CI/CD.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 2, 0, 1, 'Gérez votre infrastructure avec Terraform.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(45, 21, 'Introduction à l\'Algorithmique', 'Un algorithme est une suite d\'instructions permettant de résoudre un problème. Ce chapitre introductif présente les concepts de base : variables, constantes, opérateurs, expressions, et la représentation d\'algorithmes avec des organigrammes et du pseudo-code.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 45, 1, 1, 1, 'Qu\'est-ce qu\'un algorithme ?', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(46, 21, 'Structures de Contrôle', 'Les structures de contrôle sont essentielles : conditions (if/else, switch), boucles (for, while, do-while), et les structures conditionnelles complexes. Vous résoudrez des exercices pratiques pour maîtriser chaque concept.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 2, 0, 1, 'Conditions et boucles en algorithmique.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(47, 22, 'Listes, Piles et Files', 'Les structures de données linéaires sont la base de l\'algorithmique : listes chaînées, piles (LIFO), files (FIFO). Vous implémenterez chaque structure et découvrirez leurs applications concrètes : évaluation d\'expressions, parcours en largeur, undo/redo.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 75, 1, 0, 1, 'Les structures linéaires fondamentales.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(48, 22, 'Arbres et Graphes', 'Les arbres (binaires, AVL, B-trees) et les graphes sont au cœur de nombreux algorithmes. Vous étudierez les parcours (DFS, BFS), les arbres de recherche, et les algorithmes de plus court chemin (Dijkstra, Bellman-Ford).', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 90, 2, 0, 1, 'Les structures non linéaires et leurs parcours.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(49, 23, 'Algorithmes de Tri', 'Le tri est un problème fondamental. Vous étudierez le tri à bulles, le tri par sélection, le tri par insertion, le tri fusion, le tri rapide (quicksort). Pour chaque algorithme, nous analyserons la complexité temporelle et spatiale avec la notation Big O.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 90, 1, 0, 1, 'Les méthodes de tri classiques.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(50, 23, 'Algorithmes de Recherche', 'La recherche dans les données est une opération courante. Vous maîtriserez la recherche séquentielle, la recherche binaire (sur tableaux triés), et la recherche par interpolation. Des exercices sur des jeux de données réels pour consolider vos acquis.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 2, 0, 1, 'Recherche séquentielle, binaire et par interpolation.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(51, 24, 'Prise en main d\'Excel', 'Découvrez l\'interface d\'Excel : le ruban, les onglets, la barre de formule, les classeurs et feuilles de calcul. Vous apprendrez à saisir des données, à naviguer efficacement, à utiliser les raccourcis clavier, et à personnaliser votre environnement de travail.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 1, 1, 1, 'Interface, navigation et premiers pas.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(52, 24, 'Mise en Forme et Impression', 'La mise en forme est cruciale pour la lisibilité. Vous maîtriserez les polices, les couleurs, les bordures, la mise en forme conditionnelle, les styles de cellule, et les options d\'impression (sauts de page, entêtes, pieds de page).', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 45, 2, 0, 1, 'Présentez vos données de manière professionnelle.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(53, 25, 'Fonctions de Base', 'Les fonctions sont le cœur d\'Excel. Vous apprendrez les fonctions logiques (SI, ET, OU), les fonctions de recherche (RECHERCHEV, INDEX, EQUIV), les fonctions texte (GAUCHE, DROITE, STXT, CONCATENER), et les fonctions date (AUJOURDHUI, DATEDIF).', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 1, 0, 1, 'SOMME, MOYENNE, SI, RECHERCHEV et autres fonctions essentielles.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(54, 25, 'Fonctions Avancées', 'Passez au niveau supérieur avec les fonctions conditionnelles (SOMME.SI, NB.SI, MOYENNE.SI), la combinaison INDEX/EQUIV (alternative plus puissante à RECHERCHEV), les formules matricielles, et les nouvelles fonctions dynamiques d\'Excel 365.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 75, 2, 0, 1, 'SOMME.SI, NB.SI, INDEX/EQUIV, et formules matricielles.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(55, 26, 'Création de TCD', 'Les TCD sont l\'outil d\'analyse le plus puissant d\'Excel. Vous apprendrez à créer un TCD, à organiser les champs (lignes, colonnes, valeurs, filtres), à regrouper les données, et à ajouter des segments et des chronologies pour filtrer interactivement.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 1, 0, 1, 'Analysez vos données avec les tableaux croisés dynamiques.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(56, 26, 'Graphiques et Rapports', 'Les graphiques croisés dynamiques complètent les TCD. Vous créerez des tableaux de bord interactifs, des graphiques sparkline, des slicers, et des rapports professionnels prêts à être présentés à votre direction.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 45, 2, 0, 1, 'Visualisez vos analyses avec des graphiques percutants.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(57, 27, 'Qu\'est-ce que le Design Thinking ?', 'Le Design Thinking est une approche centrée sur l\'humain pour résoudre des problèmes complexes. Vous découvrirez l\'histoire de cette méthode développée par IDEO et Stanford, les 5 étapes du processus, et pourquoi elle est adoptée par les plus grandes entreprises innovantes.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 45, 1, 1, 1, 'Origines, principes et processus.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(58, 27, 'Les Esprits du Design Thinking', 'Le Design Thinking repose sur des mindsets spécifiques : empathie, collaboration, itération, optimisme, et tolérance à l\'échec. Vous apprendrez à cultiver ces attitudes et à constituer une équipe pluridisciplinaire pour maximiser la créativité.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 2, 0, 1, 'Adoptez la mentalité du designer.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(59, 28, 'Recherche Utilisateur', 'La phase d\'empathie vise à comprendre profondément les utilisateurs. Vous maîtriserez les techniques de recherche qualitative : entretiens individuels, observations, focus groups, et shadowing. Vous créerez des cartes d\'empathie et des personas pour synthétiser vos découvertes.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 1, 0, 1, 'Techniques d\'enquête pour comprendre vos utilisateurs.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(60, 28, 'Définir le Problème', 'La définition du problème est cruciale. Vous apprendrez à formuler un Point of View (POV) : \"Comment pourrions-nous... ?\". Vous utiliserez les outils du design thinking comme le sarcelle, la matrice 2x2, et le diagramme d\'affinité pour structurer vos insights.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 45, 2, 0, 1, 'Formulez un point de vue clair et actionnable.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(61, 29, 'Techniques d\'Idéation', 'L\'idéation est la phase de génération d\'idées. Vous pratiquerez le brainstorming, le brainwriting, le mind mapping, la technique SCAMPER, et l\'inversion des hypothèses. L\'objectif : produire un grand volume d\'idées sans s\'autocensurer.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 1, 0, 1, 'Générez un maximum d\'idées créatives.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(62, 29, 'Prototypage Rapide', 'Le prototypage permet de matérialiser une idée rapidement et à moindre coût. Vous apprendrez à créer des prototypes papier, des maquettes, des storyboards, et des wireframes. L\'objectif : échouer rapidement pour apprendre et itérer.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 75, 2, 0, 1, 'Concrétisez vos idées avec des prototypes basse fidélité.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(63, 30, 'Tests Utilisateurs', 'Les tests utilisateurs sont le cœur du Design Thinking. Vous organiserez des sessions de test, recueillerez des feedbacks, identifierez les points de friction, et itérerez sur votre prototype. Des techniques comme le A/B testing et les tests d\'utilisabilité.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 1, 0, 1, 'Testez vos prototypes avec de vrais utilisateurs.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(64, 30, 'Passer à l\'Implémentation', 'La dernière étape consiste à transformer votre prototype en solution réelle. Vous apprendrez à créer une feuille de route produit, à prioriser les fonctionnalités, à constituer une équipe de développement, et à mesurer l\'impact de votre solution avec des KPI.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 45, 2, 0, 1, 'De l\'idée au produit concret.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(65, 31, 'Les Piliers de la Communication', 'La communication est un processus complexe. Ce chapitre décrypte le schéma de communication (émetteur, récepteur, message, canal, feedback), les filtres et les biais qui perturbent le message, et les principes de la communication non-violente (CNV).', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 45, 1, 1, 1, 'Comprendre le processus de communication.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(66, 31, 'Communication Écrite et Digitale', 'À l\'ère du digital, la communication écrite est omniprésente. Vous apprendrez à rédiger des emails professionnels, des messages sur Slack/Teams, des rapports concis, et à adapter votre ton selon votre interlocuteur. La règle d\'or : clarté et concision.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 45, 2, 0, 1, 'Rédigez des messages clairs et impactants.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(67, 32, 'Préparer son Intervention', 'Une bonne préparation est la clé d\'une intervention réussie. Vous apprendrez à définir votre objectif, à analyser votre auditoire, à structurer votre discours (introduction, développement, conclusion), et à préparer des supports visuels percutants avec la méthode Pecha Kucha.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 1, 0, 1, 'Structurez et préparez votre discours.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(68, 32, 'Gestion du Trac et du Stress', 'Le trac est naturel, mais il peut être maîtrisé. Vous découvrirez des techniques de respiration, de visualisation positive, d\'ancrage, et de préparation mentale. Des exercices pratiques pour transformer votre stress en énergie positive.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 45, 2, 0, 1, 'Techniques pour rester serein face à l\'auditoire.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(69, 33, 'Le Langage Corporel', 'La communication non verbale représente 70% de notre message. Vous apprendrez à maîtriser votre posture, à utiliser des gestes ouverts et confiants, à contrôler vos expressions faciales, et à lire le langage corporel de votre interlocuteur.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 1, 0, 1, 'Posture, gestes et expressions faciales.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(70, 33, 'Le Paralangage', 'Le paralangage englobe tout ce qui accompagne la parole : le ton, le débit, le volume, les pauses, et les silences. Vous travaillerez votre voix avec des exercices de diction, de respiration, et de modulation pour captiver votre auditoire.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 45, 2, 0, 1, 'Voix, rythme, intonation et silences.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(71, 34, 'Le Manifeste Agile', 'Le manifeste agile a révolutionné la gestion de projet. Vous découvrirez les 4 valeurs fondamentales (individus et interactions, logiciel fonctionnel, collaboration client, adaptation au changement) et les 12 principes qui guident les méthodes agiles comme Scrum et Kanban.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 45, 1, 1, 1, 'Les valeurs et principes du développement agile.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(72, 34, 'Agile vs Traditionnel', 'Quand utiliser l\'agile plutôt que le cycle en V ou le waterfall ? Ce chapitre compare les approches, explique les critères de choix, et présente les frameworks agiles les plus populaires : Scrum, Kanban, XP, et SAFe pour les grandes organisations.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 2, 0, 1, 'Comparaison des approches prédictives et adaptatives.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(73, 35, 'Les Rôles Scrum', 'Scrum définit trois rôles avec des responsabilités claires. Le Product Owner maximise la valeur du produit, le Scrum Master facilite le processus, et les Developers s\'auto-organisent pour livrer l\'incrément. Vous comprendrez les interactions et les responsabilités de chaque rôle.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 1, 0, 1, 'Scrum Master, Product Owner et Developers.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(74, 35, 'Les Événements Scrum', 'Les événements Scrum créent du rythme et de la transparence. Vous détaillerez chaque événement : le Sprint Planning (quoi et comment), le Daily Scrum (synchronisation), la Sprint Review (inspection et adaptation du produit), et la Rétrospective (amélioration continue).', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 75, 2, 0, 1, 'Sprint, Daily Scrum, Sprint Review et Rétrospective.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(75, 36, 'Les Artefacts Scrum', 'Les artefacts Scrum sont des engagements qui garantissent la transparence. Le Product Backlog est la liste ordonnée des fonctionnalités, le Sprint Backlog est le plan pour le sprint, et l\'Incrément est le résultat livrable. Vous apprendrez à les gérer efficacement.', 'video', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, 1, 0, 1, 'Product Backlog, Sprint Backlog et Incrément.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(76, 36, 'Préparation à la Certification Scrum Master', 'Ce chapitre vous prépare à l\'examen Professional Scrum Master I. Vous trouverez des quiz, des études de cas, des simulations d\'examen, et des conseils pour réussir du premier coup. La certification Scrum Master est un atout majeur sur le marché du travail.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 90, 2, 0, 1, 'Passez la certification PSM I avec succès.', '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(77, 37, 'Bienvenue et objectifs du parcours', '', 'video', NULL, 'demo/welcome-to-the-course.mp4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 5, 1, 1, 1, 'Présentation du parcours, des livrables et des critères de certification.', '2026-07-28 00:42:31', '2026-07-28 00:42:31'),
(78, 37, 'Cadre de gouvernance des risques', '# Gouvernance des risques\n\nUne gouvernance efficace relie la stratégie, les opérations et le contrôle interne.\n\n## Les trois lignes\n\n1. **Métiers** — identifient et traitent les risques au quotidien.\n2. **Fonctions de supervision** — définissent le cadre et accompagnent les métiers.\n3. **Audit interne** — fournit une assurance indépendante.\n\n> Livrable attendu : une matrice RACI validée par la direction.\n\n~~~mermaid\nflowchart LR\n    A[Conseil] --> B[Direction générale]\n    B --> C[Métiers]\n    B --> D[Risque et conformité]\n    A --> E[Audit interne]\n~~~', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 18, 2, 0, 1, 'Rôles, responsabilités et modèle des trois lignes.', '2026-07-28 00:42:31', '2026-07-28 00:42:31'),
(79, 38, 'Construire un registre des risques', '# Registre des risques\n\nTéléchargez le support PDF, puis appliquez la méthode au cas proposé.', 'pdf', 'demo/risk-register-workbook.pdf', NULL, NULL, NULL, 'completed', NULL, '{\"page_count\":3,\"document_type\":\"native\",\"extraction_strategy\":\"text-first\"}', NULL, '2026-07-28 00:42:31', 35, 1, 0, 1, 'Support pratique avec méthode, exemple et grille de cotation.', '2026-07-28 00:42:31', '2026-07-28 00:42:31'),
(80, 38, 'Prioriser les plans de traitement', '# Plan de traitement\n\nChaque action doit posséder un responsable, une échéance, un budget et un indicateur de résultat.\n\n| Stratégie | Usage recommandé | Exemple |\n|---|---|---|\n| Réduire | Risque maîtrisable | Double validation des paiements |\n| Transférer | Impact financier élevé | Assurance cyber |\n| Accepter | Coût disproportionné | Tolérance documentée |\n| Éviter | Activité hors appétence | Arrêt du processus |', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 22, 2, 0, 1, 'Arbitrer entre réduction, transfert, acceptation et évitement.', '2026-07-28 00:42:31', '2026-07-28 00:42:31'),
(81, 39, 'Concevoir un tableau de bord de risques', '# Reporting exécutif\n\nUn bon indicateur est relié à une décision. Présentez la tendance, le seuil d’alerte, le responsable et l’action attendue.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 20, 1, 0, 1, 'Choisir des KRI lisibles et actionnables par le comité de direction.', '2026-07-28 00:42:31', '2026-07-28 00:42:31'),
(82, 40, 'Types de sols et études géotechniques', '# Types de sols\n\n## Classification\n- **Sols rocheux** : granite, calcaire, schiste — excellente portance.\n- **Sols meubles** : argile, sable, limon, gravier — portance variable.\n- **Sols organiques** : tourbe, vase — à éviter.\n\n## Étude géotechnique\nNorme NF P 94-500 :\n1. **G1** : reconnaissance sommaire.\n2. **G2** : investigation détaillée (sondages, essais).\n3. **G3** : suivi géotechnique d\'exécution.\n\n## Essais\n| Essai | Mesure |\n|---|---|\n| Pénétromètre | Résistance de pointe |\n| Pressiomètre | Module de déformation |', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 1, 1, 1, 'Comprendre les sols avant de construire.', '2026-07-28 00:42:31', '2026-07-28 00:42:31'),
(83, 40, 'Réalisation des fondations', '# Réalisation des fondations\n\n## Fondations superficielles\n- **Semelle filante** : sous murs porteurs, largeur ≥ 40 cm.\n- **Semelle isolée** : sous poteaux.\n- **Radier** : dalle épaisse, idéal pour sols hétérogènes.\n\n## Fondations profondes\n- **Pieux battus** : préfabriqués, enfoncés par battage.\n- **Pieux forés** : réalisés dans le sol, Ø 40–120 cm.\n\n## Étapes\n1. Implantation et piquetage.\n2. Fouille en tranchée.\n3. Béton de propreté (5 cm).\n4. Ferraillage (enrobage ≥ 5 cm).\n5. Coulage béton C25/30.\n6. Cure et décoffrage (7 jours min).', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 45, 2, 0, 1, 'Semelles, radier et pieux.', '2026-07-28 00:42:31', '2026-07-28 00:42:31'),
(84, 40, 'Drainage et étanchéité', '# Drainage et étanchéité\n\n## Drainage périphérique\n- **Drain vertical** : membrane rugueuse sur mur enterré.\n- **Drain horizontal** : tube DN 100, enveloppé de géotextile.\n- **Couche drainante** : gravier 20/40 mm.\n\n## Étanchéité\n- Enduit bitumineux à froid ou à chaud.\n- Membrane PVC/EPDM pour sous-sols habitables.\n- Cuvelage par mortiers hydrofuges.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, 0, 1, 'Protéger les fondations contre l\'humidité.', '2026-07-28 00:42:31', '2026-07-28 00:42:31'),
(85, 41, 'Techniques de maçonnerie', '# Techniques de maçonnerie\n\n## Parpaings\n- Dimensions : 20×20×50 cm.\n- Joints verticaux décalés.\n- Épaisseur joints : 1–1,5 cm.\n\n## Briques\n- **Pleine** : pour murs porteurs.\n- **Creuse** : pour cloisons.\n- **Monomur** : isolation intégrée.\n\n## Pierres\n- **Moellon** : brute, joints larges.\n- **Pierre de taille** : régulière, joints minces.\n- **Pierre sèche** : sans mortier.\n\n## Règles\n- Mouiller les supports.\n- Respecter l\'équerrage (niveau à bulle).\n- Araser chaque rangée.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 50, 1, 0, 1, 'Parpaings, briques et pierres.', '2026-07-28 00:42:31', '2026-07-28 00:42:31'),
(86, 41, 'Chaînages et ferraillage', '# Chaînages et ferraillage\n\n## Types\n- **Horizontal** : en tête de mur (ceinture).\n- **Vertical** : aux extrémités des murs.\n- **En redans** : murs de soutènement.\n\n## Ferraillage minimal\n| Élément | Aciers |\n|---|---|\n| Chaînage horizontal | 4 HA 10 + cadres HA 6 t. 25 cm |\n| Chaînage vertical | 4 HA 12 + cadres HA 6 t. 20 cm |\n| Linteau | 2 HA 8 en partie inférieure |\n\n## Dispositions\n- Enrobage : ≥ 2,5 cm intérieur, ≥ 5 cm extérieur.\n- Recouvrement : 40–50 × diamètre.\n- Norme : DTU 23.1 et Eurocode 6.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 40, 2, 0, 1, 'Assurer la tenue mécanique de la structure.', '2026-07-28 00:42:31', '2026-07-28 00:42:31'),
(87, 41, 'Ouvertures et linteaux', '# Ouvertures et linteaux\n\n## Types\n- Béton armé préfabriqué (le plus répandu).\n- Métallique (UPE, HEA) pour grandes portées.\n- Bois pour ossature bois.\n\n## Pose\n1. Étairement provisoire (tous les 1,5 m).\n2. Saignée de chaque côté.\n3. Pose sur appuis ≥ 20 cm.\n4. Béton de calage.\n5. Dépose étais après 7 jours.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, 0, 1, 'Créer des trémies dans les murs porteurs.', '2026-07-28 00:42:31', '2026-07-28 00:42:31'),
(88, 42, 'Types de planchers', '# Types de planchers\n\n## Plancher à hourdis\n- Poutrelles + entrevous + coulage.\n- Portée jusqu\'à 6 m.\n\n## Dalle pleine\n- Épaisseur 15–25 cm.\n- Portée jusqu\'à 8 m.\n- Grande rigidité.\n\n## Prédalle\n- Préfabriquée, épaisseur 5–8 cm + couche compression 15–20 cm.\n- Rapide à poser.\n- Portée jusqu\'à 12 m.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 1, 0, 1, 'Hourdis, dalle pleine, prédalle.', '2026-07-28 00:42:31', '2026-07-28 00:42:31'),
(89, 42, 'Réalisation d\'un dallage', '# Dallage sur terre-plein\n\n1. Terrassement (30–50 cm).\n2. Couche de forme (grave compactée 20–30 cm).\n3. Film polyane (pare-vapeur).\n4. Isolation thermique (PSE/XPS).\n5. Ferraillage (treillis soudé ST 25C, enrobage ≥ 3 cm).\n6. Coulage béton C25/30 (15–20 cm).\n7. Joint de dilatation (tous les 25–30 m²).\n8. Cure (7 jours minimum).', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 40, 2, 0, 1, 'Les étapes clés du dallage sur terre-plein.', '2026-07-28 00:42:31', '2026-07-28 00:42:31'),
(90, 42, 'Isolation des planchers', '# Isolation des planchers\n\n## Thermique\n- Sous dalle : PSE ou XPS.\n- Chape flottante : isolant + treillis + chape 5–6 cm.\n- Plancher chauffant : tubes PEX noyés dans la chape.\n\n## Acoustique\n- Bruits d\'impact : résilients sous chape (laine minérale, caoutchouc).\n- Bruits aériens : masse surfacique élevée.\n- Bandes résilientes en périmètre.\n\n## Réglementation\n- RE 2020 : R ≥ 3 m².K/W pour planchers bas.\n- NRA : L\'nT,w ≤ 58 dB.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, 0, 1, 'Confort thermique et acoustique.', '2026-07-28 00:42:31', '2026-07-28 00:42:31'),
(91, 43, 'Lois de base de l\'électricité', '# Lois de base\n\n## Grandeurs\n- **Tension (U)** : volts (V).\n- **Courant (I)** : ampères (A).\n- **Résistance (R)** : ohms (Ω).\n\n## Lois fondamentales\n- Loi d\'Ohm : **U = R × I**\n- Puissance : **P = U × I**\n- Joule : **W = R × I² × t**\n\n## Applications\n| Formule | Exemple |\n|---|---|\n| U = R × I | 230 V = 10 Ω × 23 A |\n| I = P / U | 10 A = 2300 W / 230 V |\n| R = U / I | 23 Ω = 230 V / 10 A |', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 1, 1, 1, 'Tension, courant, résistance et puissance.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(92, 43, 'Schémas et symboles normalisés', '# Schémas électriques\n\n## Types\n- **Unifilaire** : vision simplifiée.\n- **Multifilaire** : tous les conducteurs.\n- **Architectural** : implanté sur le plan.\n\n## Codes couleurs (NF C 15-100)\n- Phase : rouge/marron.\n- Neutre : bleu.\n- Terre : vert-jaune.\n\n## Règles\n- Section des conducteurs adaptée.\n- Repérage des circuits au tableau.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 2, 0, 1, 'Lire et réaliser des schémas d\'installation.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(93, 43, 'Protection des circuits', '# Protection des circuits\n\n## Disjoncteurs\n- **Magnétique** : court-circuit.\n- **Thermique** : surcharge.\n- **Magnéto-thermique** : les deux.\n\n## Interrupteurs différentiels\n- **Type AC** : circuits standard.\n- **Type A** : circuits électroniques.\n- **Type F** : variateurs.\n\n## Fusibles\n- À cartouche ou à couteau.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 3, 0, 1, 'Disjoncteurs, fusibles et différentiels.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(94, 44, 'Tableau électrique et distribution', '# Tableau électrique\n\n## Éléments\n- Interrupteur général (DG) : 30–60 A.\n- Interrupteurs différentiels : 2–4 par tableau.\n- Disjoncteurs divisionnaires : 1 par circuit.\n- Bornier de terre.\n\n## Circuits (NF C 15-100)\n| Circuit | Section | Protection |\n|---|---|---|\n| Prises | 2,5 mm² | 20 A |\n| Éclairage | 1,5 mm² | 16 A |\n| Cuisinière | 6 mm² | 32 A |\n| Lave-linge | 2,5 mm² | 20 A |\n\n## Règles\n- Repérage par couleur.\n- Longueur max : 100 m (2,5 mm²).', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 45, 1, 0, 1, 'Conception et câblage du tableau.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(95, 44, 'Prise de terre et mise à la masse', '# Prise de terre\n\n## Électrodes\n- Boucle à fond de fouille (cuivre nu 25 mm²).\n- Piquet de terre (≥ 2 m).\n\n## Valeurs\n- 100 Ω max (logement individuel).\n- Mesure au telluromètre.\n\n## Mise à la masse\nToutes les masses métalliques accessibles reliées à la terre : boîtiers, huisseries, canalisations, goulottes.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 2, 0, 1, 'Protection contre les défauts d\'isolement.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(96, 44, 'Éclairage et prises', '# Éclairage et prises\n\n## Éclairage\n- 1 point pour 4 m de périmètre.\n- Interrupteur à 1,20 m du sol.\n- Va-et-vient pour dégagements > 3 m.\n\n## Prises\n- 3 prises minimum par pièce + 1/4 m².\n- Hauteur : 15–30 cm du sol.\n- 8 prises max par circuit en 2,5 mm².\n- 8 points d\'éclairage max par circuit en 1,5 mm².', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, 0, 1, 'Pose des points d\'usage courants.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(97, 45, 'Réseaux VDI', '# Réseaux VDI\n\n## Supports\n- Paire torsadée RJ45 (cat. 6a/7).\n- Fibre optique FTTH.\n- Coaxial TV/satellite.\n\n## Normes\n- NF C 15-100 : 1 point communication/pièce.\n- EIA/TIA 568 : câblage structuré.\n\n## Installation\n1. Tirage en gaines séparées des conducteurs électriques.\n2. Rayon courbure ≥ 4 × Ø.\n3. Longueur max : 90 m.\n4. Test de certification.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 1, 0, 1, 'Voix, données, images : câblage structuré.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(98, 45, 'Systèmes de sécurité', '# Systèmes de sécurité\n\n## Alarme intrusion\n- Détecteurs d\'ouverture (contacts magnétiques).\n- Détecteurs volumétriques (infrarouge).\n- Centrale communicante GSM/IP.\n\n## Vidéosurveillance\n- Caméras IP HD/4K, vision nocturne.\n- Enregistreur NVR (local/cloud).\n- Alimentation PoE.\n\n## Contrôle d\'accès\n- Badge RFID, code digital, biométrie.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 40, 2, 0, 1, 'Alarme, vidéosurveillance et contrôle d\'accès.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(99, 45, 'Domotique et GTB', '# Domotique\n\n## Protocoles\n- **KNX** : standard international GTB.\n- **Zigbee/Z-Wave** : maison connectée.\n- **Modbus/BACnet** : bâtiment tertiaire.\n\n## Fonctions\n- Éclairage : variation, scénarios.\n- Chauffage : programmation, zones.\n- Volets : motorisation solaire.\n- Supervision : écran tactile/smartphone.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 3, 0, 1, 'Gestion technique du bâtiment.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(100, 46, 'Canalisations et matériaux', '# Canalisations\n\n## Cuivre\n- Durable, bactériostatique.\n- Assemblage par soudure (brasure).\n- Ø 12, 14, 16, 18, 22 mm.\n\n## PER\n- Flexible, résiste au gel.\n- Raccords à sertir ou bagues coulissantes.\n- Pour distribution enterrée et plancher chauffant.\n\n## Multicouche\n- Rigidité du cuivre + flexibilité du PER.\n- Sertissage avec pince adaptée.\n\n## Diamètres\n| Usage | Ø |\n|---|---|\n| Alimentation générale | 22–28 mm |\n| Distribution secondaire | 14–18 mm |\n| Alimentation appareil | 12–14 mm |', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 1, 1, 1, 'Cuivre, PER, multicouche.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(101, 46, 'Dimensionnement et pose', '# Dimensionnement\n\n## Débits forfaitaires\n| Appareil | Débit (L/min) |\n|---|---|\n| Lavabo | 10 |\n| Douche | 12 |\n| Baignoire | 15 |\n| WC | 6 |\n\n## Pose\n- Pente ≥ 1 % pour vidange.\n- Colliers : cuivre 12 mm → 1 m, 22 mm → 1,5 m.\n- Isolation eau chaude (≥ 10 mm).', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 2, 0, 1, 'Calcul et règles de pose.', '2026-07-28 00:42:32', '2026-07-28 00:42:32');
INSERT INTO `chapters` (`id`, `section_id`, `title`, `content`, `content_type`, `media_url`, `video_url`, `cover_image`, `markdown_file`, `processing_status`, `processing_error`, `processing_metadata`, `processing_started_at`, `processed_at`, `duration_minutes`, `order_position`, `is_free`, `is_active`, `description`, `created_at`, `updated_at`) VALUES
(102, 46, 'Production d\'eau chaude', '# Production d\'eau chaude\n\n## Types\n- Électrique à accumulation (50–300 L).\n- Thermodynamique (PAC intégrée).\n- Solaire (capteurs + ballon).\n\n## Groupe de sécurité (NF EN 1487)\n- Clapet anti-retour.\n- Soupape à 7 bars.\n- Dispositif de vidange.\n\n## Raccordement\n- Eau froide : groupe de sécurité sur le ballon.\n- Eau chaude : repéré en rouge.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, 0, 1, 'Chauffe-eau et groupes de sécurité.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(103, 47, 'Évacuation des eaux usées', '# Évacuation\n\n## Réseaux\n- Eaux usées : lavabos, douches, éviers.\n- Eaux-vannes : WC.\n- Eaux pluviales : toitures.\n\n## Matériaux\n- PVC (Ø 32–110 mm).\n- PP (haute température).\n- Fonte (isolation phonique).\n\n## Pentes\n| Ø | Pente mini |\n|---|---|\n| 32–40 mm | 2 % |\n| 50–75 mm | 1,5 % |\n| 100–110 mm | 1 % |\n\n## Regards de visite\nTous les 15 m maximum, aux changements de direction.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 1, 0, 1, 'Conception et pose des collecteurs.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(104, 47, 'Ventilation et colonnes de chute', '# Ventilation\n\n## Primaire\nProlongement de la colonne de chute à l\'air libre.\n\n## Secondaire\nCircuit parallèle connectant les appareils à la ventilation primaire.\n\n## Rôle\n1. Éviter la dépression (anti-siphonnage).\n2. Évacuer les gaz.\n3. Réduire le bruit.\n\n## Colonne de chute\n- Ø mini : 100 mm (WC), 75 mm (autres).\n- Distance max appareil → colonne : 3 m.\n- Pied de colonne à 45°.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 2, 0, 1, 'Équilibre du réseau d\'évacuation.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(105, 48, 'Pose des appareils sanitaires', '# Appareils sanitaires\n\n## WC\n- Classique ou suspendu (bâti-support).\n- Hauteur cuvette : 40–42 cm.\n\n## Lavabo\n- Hauteur : 82–86 cm.\n- Mitigeur entraxe 15 cm.\n\n## Douche\n- Receveur ou carrelée à l\'italienne.\n- Étanchéité obligatoire.\n- Pente ≥ 1,5 %.\n\n## Baignoire\n- Support réglable ou lit de mortier.\n- Vidage avec trop-plein.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 40, 1, 0, 1, 'WC, lavabo, douche, baignoire.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(106, 48, 'Robinetterie et mitigeurs', '# Robinetterie\n\n## Types\n- Tête céramique (1/4 tour).\n- Mitigeur mécanique.\n- Mitigeur thermostatique.\n\n## Normes\n- NF : conformité qualité.\n- ACS : conformité sanitaire eau potable.\n\n## Pose\n1. Tresses flexibles + joints.\n2. Serrage main + 1/4 tour à la pince.\n3. Eau chaude à gauche, froide à droite.\n4. Test en pression.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 2, 0, 1, 'Choix, pose et entretien.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(107, 49, 'Essences de bois', '# Essences de bois\n\n## Résineux\n- **Pin sylvestre** : charpente, menuiserie courante.\n- **Sapin/Épicéa** : ossature bois.\n- **Douglas** : menuiseries extérieures.\n\n## Feuillus\n- **Chêne** : meubles, parquets.\n- **Hêtre** : meubles, sièges.\n- **Noyer** : ébénisterie fine.\n\n## Exotiques\n- **Teck** : imputrescible, extérieur.\n- **Iroko** : menuiseries extérieures.\n\n## Critères\n| Critère | Résineux | Feuillus | Exotiques |\n|---|---|---|---|\n| Coût | Faible | Moyen | Élevé |\n| Dureté | Faible | Moy/Fort | Très fort |\n| Durabilité | Moyenne | Bonne | Excellente |', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 1, 1, 1, 'Connaître les bois pour mieux les travailler.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(108, 49, 'Panneaux dérivés du bois', '# Panneaux dérivés\n\n## Contreplaqué\n- CTBH (intérieur), CTBX (extérieur).\n- Plis de bois croisés collés.\n\n## MDF\n- Fibres comprimées, surface lisse.\n- Sensible à l\'humidité.\n\n## Aggloméré\n- Particules collées, économique.\n- Pour meubles d\'entrée de gamme.\n\n## OSB\n- Lamelles orientées, structurel.\n- Âmes de portes, murs, toiture.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 25, 2, 0, 1, 'Contreplaqué, MDF, aggloméré, OSB.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(109, 50, 'Assemblage et quincaillerie', '# Assemblage\n\n## Traditionnels\n- **Tenon-mortaise** : le plus solide.\n- **Queue-d\'aronde** : tiroirs.\n- **À mi-bois** : cadres.\n\n## Modernes\n- Tourillons, Lamello.\n- Vis et confirmats (agencement).\n\n## Quincaillerie\n| Type | Usage |\n|---|---|\n| Paumelle | Porte d\'armoire |\n| Charnière | Porte cuisine |\n| Glissière | Tiroir |\n| Crémone | Fenêtre |', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 1, 0, 1, 'Techniques traditionnelles et modernes.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(110, 50, 'Usinage du bois', '# Usinage\n\n## Sciage\n- Circulaire : coupes rapides.\n- À ruban : coupes courbes.\n- Sauteuse : découpes de forme.\n\n## Rabotage\n- Rabot électrique : dégrossissage.\n- Dégauchisseuse : dressage.\n- Corroyeuse : épaisseur.\n\n## Fraisage (défonceuse)\n- Fraise à tenon, à queue-d\'aronde, à moulure.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 2, 0, 1, 'Sciage, rabotage, perçage, fraisage.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(111, 50, 'Finition du bois', '# Finition\n\n## Ponçage\n| Grain | Usage |\n|---|---|\n| 40–60 | Dégrossissage |\n| 80–120 | Préparation |\n| 180–240 | Finition |\n| 320–400 | Entre couches |\n\n## Vernis\n- Polyuréthane (résistant).\n- Acrylique (à l\'eau).\n- Marin (extérieur UV).\n\n## Cire\n- D\'abeille (aspect satiné).\n- Dure à l\'alcool.\n\n## Peinture\n- Sous-couche obligatoire.\n- Ponçage entre couches.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, 0, 1, 'Ponçage, vernis, cire, peinture.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(112, 51, 'Menuiseries extérieures', '# Menuiseries extérieures\n\n## Fenêtres bois\n- Massif ou lamellé-collé.\n- Double vitrage 4/16/4.\n- Quincaillerie : paumelles, crémone.\n\n## Portes d\'entrée\n- Pleine ou vitrée.\n- Seuil aluminium avec rupture pont thermique.\n- Serrure 3 points (A2P).\n\n## Volets\n- Battants, pliants ou roulants.\n- Traitement autoclave classe 3/4.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 1, 0, 1, 'Fenêtres, portes et volets.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(113, 51, 'Menuiseries intérieures', '# Menuiseries intérieures\n\n## Escaliers\n- Droit, quart tournant, hélicoïdal.\n- Giron : 23–30 cm.\n- Hauteur marche : 16–21 cm.\n- Largeur mini : 70 cm.\n- Garde-corps ≥ 90 cm.\n\n## Parquets\n- Massif (≥ 14 mm) ou contrecollé.\n- Pose clouée, collée ou flottante.\n\n## Placards\n- Sous pente, dressing, bibliothèques.\n- Portes coulissantes ou battantes.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 2, 0, 1, 'Escaliers, parquets et placards.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(114, 51, 'Agencement sur mesure', '# Agencement sur mesure\n\n## Processus\n1. Prise de mesures.\n2. Plan CAO (TopSolid, Cabinet Vision).\n3. Validation client.\n4. Débit + optimisation.\n5. Usinage et assemblage.\n6. Finition + quincaillerie.\n7. Pose sur site.\n\n## Matériaux\n- MDF laqué (façades).\n- Contreplaqué (structure).\n- Mélaminé (intérieur).', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 25, 3, 0, 1, 'Conception et fabrication de meubles.', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(115, 52, 'Diagnostic des supports', '# Diagnostic des supports\n\n## Types\n- Plâtre : poreux, sous-couche.\n- Béton : lisse, à traiter.\n- Bois : noeuds à bloquer.\n- Métal : antirouille.\n\n## Traitements\n- Nettoyage, décapage.\n- Rebouchage des trous et fissures.\n- Traitement moisissures (eau de javel/fongicide).\n\n## Test d\'adhérence\nQuadrillage + ruban adhésif : si décollement, support non sain.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 1, 1, 1, 'Analyser et préparer les surfaces.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(116, 52, 'Enduits de lissage et rebouchage', '# Enduits\n\n## Types\n- **Rebouchage** : petits trous.\n- **Lissage** : grandes surfaces (1–3 mm).\n- **Garnissage** : défauts profonds (5–10 mm).\n- **Finition** : dernière passe.\n\n## Application\n1. Au couteau à enduire.\n2. Lisser en croisant.\n3. Ponçage (grain 120–180).\n4. Dépoussiérage.\n\n## Séchage\n- Poudre : 30–60 min.\n- Prêt à l\'emploi : 2–4 h.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 2, 0, 1, 'Obtenir une surface parfaitement lisse.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(117, 52, 'Sous-couches et primaires', '# Sous-couches\n\n## Rôle\n1. Uniformiser l\'absorption.\n2. Améliorer l\'adhérence.\n3. Masquer les différences de couleur.\n\n## Par support\n| Support | Primaire |\n|---|---|\n| Plâtre neuf | Acrylique |\n| Béton | Accrochage |\n| Bois | Anti-nœuds |\n| Métal | Antirouille |\n| Ancienne peinture satinée | Adhérence |\n\n## Application\n1 couche, ponçage léger grain 180 après séchage.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 25, 3, 0, 1, 'Garantir l\'adhérence de la peinture.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(118, 53, 'Application au rouleau et pinceau', '# Application\n\n## Rouleau\n- Manchon à poils longs (plafond), courts (lisse).\n- Tracer un W, croiser sans recharger.\n\n## Pinceau\n- Plat (grandes surfaces), rond (détails).\n- Brosse à rechampir (finitions).\n\n## Pistolet\n- Airless (grandes surfaces).\n- Pneumatique (finition soignée).\n\n## Ordre\n1. Plafond.\n2. Murs (haut → bas).\n3. Boiseries.\n4. Sol.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 1, 0, 1, 'Les gestes professionnels.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(119, 53, 'Papiers peints et revêtements', '# Revêtements muraux\n\n## Types\n- Papier traditionnel.\n- **Intissé** : colle au mur, se retire à sec.\n- Toile de verre : à peindre après pose.\n- Vinyle : lessivable.\n\n## Pose intissé\n1. Encollage du mur.\n2. Pose du lé.\n3. Marouflage (centre → bords).\n4. Découpe cutter.\n5. Raccord bord à bord.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 2, 0, 1, 'Pose de papier peint, intissé et toile de verre.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(120, 53, 'Effets décoratifs', '# Effets décoratifs\n\n## Patine\n- À l\'éponge, au chiffon ou à la brosse.\n\n## Stuc\n- À la chaux (aspect pierre) ou à l\'huile (effet marbre).\n- 5–10 couches fines.\n\n## Béton ciré\n- 1–3 mm au couteau à enduire.\n- Finition satinée ou mate.\n\n## Tadelakt\n- Enduit chaux marocain.\n- 3 couches, lissage à la pierre d\'agate.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 3, 0, 1, 'Patine, stuc, béton ciré, tadelakt.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(121, 54, 'Lasures et vernis', '# Lasures et vernis\n\n## Lasure\n- Micro-poreuse (extérieur).\n- Satinée (intérieur).\n- Entretien : 3–5 ans.\n\n## Vernis\n- Brillant (parquet vitrifié).\n- Satiné (meubles).\n- Mat (ébénisterie).\n\n## Application vernis\n1. Ponçage grain 240.\n2. Dépoussiérage.\n3. Couche fine.\n4. Ponçage entre couches grain 320.\n5. 2–4 couches.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 1, 0, 1, 'Protéger et sublimer les boiseries.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(122, 54, 'Peinture de sols et résines', '# Sols et résines\n\n## Peinture sol\n- Acrylique ou polyuréthane.\n- Décapage + dégraissage préalable.\n\n## Résines\n- **Époxy** : haute résistance mécanique et chimique.\n- **Polyuréthane** : souple, résistante UV.\n- **Mortier autonivelant** : sols industriels.\n\n## Application époxy\n1. Primaire d\'accrochage.\n2. Mélange résine + durcisseur.\n3. Raclette crantée.\n4. Débullage (rouleau à picots).\n5. Polymérisation 24–48 h.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 2, 0, 1, 'Revêtements techniques et décoratifs.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(123, 55, 'Procédés de soudage', '# Procédés\n\n## Arc (MMA/SMAW)\n- Électrode enrobée, arc électrique.\n- Acier carbone, simple et polyvalent.\n\n## MIG/MAG (GMAW)\n- MIG : gaz inerte (Ar) pour alu/inox.\n- MAG : gaz actif (CO₂) pour acier.\n- Fil dévidé en continu, productif.\n\n## TIG (GTAW)\n- Électrode tungstène non fusible.\n- Haute qualité, inox/alu/titane.\n\n## Oxycoupage\n- Découpe par oxydation.\n- Acier 5–300 mm.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 1, 1, 1, 'Arc, MIG/MAG, TIG, oxycoupage.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(124, 55, 'Métaux d\'apport et gaz', '# Métaux d\'apport et gaz\n\n## Métaux d\'apport\n| Procédé | Apport |\n|---|---|\n| Arc rutile | Acier général |\n| Arc basique | Acier épais |\n| MIG fil massif | Acier, alu |\n| TIG baguette | Inox, alu |\n\n## Gaz\n| Gaz | Usage |\n|---|---|\n| Argon 100 % | TIG, MIG alu/inox |\n| CO₂ 100 % | MAG acier |\n| Ar/CO₂ 82/18 | MAG acier |\n\n## Sécurité\n- Stockage debout, chaîné.\n- Détendeur adapté.\n- Ventilation obligatoire.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 2, 0, 1, 'Choix du métal d\'apport et du gaz.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(125, 55, 'Sécurité en soudage', '# Sécurité\n\n## EPI\n- Casque à filtre auto (DIN 5–13).\n- Gants cuir longs.\n- Vêtements ignifugés.\n- Chaussures sécurité.\n- Masque à cartouche (fumées).\n\n## Risques\n| Risque | Prévention |\n|---|---|\n| Brûlures | EPI + écran |\n| Fumées toxiques | Ventilation |\n| Incendie | Extincteur |\n| Électrocution | Câbles OK, mise à terre |\n\n## Règles\n- Zone ventilée.\n- Écran autour de la zone.\n- Attendre refroidissement.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 25, 3, 0, 1, 'EPI et prévention des risques.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(126, 56, 'Soudage des aciers', '# Soudage des aciers\n\n## Acier carbone\n- Préparation : brossage, meulage.\n- Préchauffage > 30 mm (150–300 °C).\n- Paramètres MAG : 18–22 V, 150–250 A.\n- Vitesse : 25–45 cm/min.\n\n## Inox\n- TIG baguette ER308L, Argon 100 %.\n- Risque : sensibilisation 450–850 °C.\n\n## Défauts\n| Défaut | Cause |\n|---|---|\n| Porosité | Manque gaz |\n| Manque pénétration | Intensité faible |\n| Crique | Refroidissement rapide |', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 1, 0, 1, 'Paramètres pour acier carbone et allié.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(127, 56, 'Soudage de l\'aluminium', '# Soudage aluminium\n\n## Particularités\n- Oxyde d\'alumine (fusion à 2050 °C).\n- Conductivité thermique élevée.\n- Dilatation importante.\n\n## TIG\n- Courant alternatif (AC).\n- Tungstène thorié Ø 2,4 mm.\n- Baguette ER4043 ou ER5356.\n- Argon 10–15 L/min.\n\n## MIG\n- Pistolet push-pull.\n- Fil ER4043/ER5356 Ø 1,0–1,6 mm.\n- 20–24 V, 150–250 A.\n\n## Défauts\n- Craquelures (fissuration à chaud).\n- Porosité (hydrogène).', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 2, 0, 1, 'Particularités de l\'aluminium.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(128, 57, 'Serrurerie et ferronnerie', '# Serrurerie\n\n## Portails\n- Tube acier 40×40 ou 60×60 mm.\n- Galvanisé + thermolaquage.\n- Serrure 3 points, motorisation.\n\n## Garde-corps\n- Hauteur : ≥ 100 cm (tertiaire), ≥ 90 cm (logement).\n- Écartement ≤ 11 cm (sécurité enfants).\n- Main courante Ø 40–50 mm.\n\n## Ferronnerie décorative\n- Volutes cintrées à chaud/froid.\n- Fers plats 20×5 mm, carrés 12×12 mm.\n- Norme NF P 01-012, NF EN 1090.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 1, 0, 1, 'Portails, rampes, garde-corps.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(129, 57, 'Charpentes métalliques', '# Charpentes métalliques\n\n## Profils\n- **IPE** : portées jusqu\'à 15 m.\n- **HEA/HEB** : fortes charges.\n- **UPN** : pannes, lisses.\n- **RHS/SHS** : poteaux, poutres.\n\n## Conception\n- Eurocode 3 (NF EN 1993).\n- Assemblages boulonnés (HR) ou soudés.\n- Contreventement (croix Saint-André).\n\n## Fabrication\n1. Tracé et débit.\n2. Perçage.\n3. Soudage atelier (MAG/arc).\n4. Grenaillage + peinture.\n5. Marquage et contrôle.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 2, 0, 1, 'Profils, fabrication, montage.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(130, 58, 'Types de supports et diagnostic', '# Supports\n\n## Types\n- Dalle béton : idéal.\n- Chape ciment : traditionnelle.\n- Chape anhydrite : primer obligatoire.\n- Plancher bois : désolidarisation.\n- Carrelage existant : dépolir + primaire.\n\n## Diagnostic\n- Quadrillage + sonorité.\n- Planéité : règle 2 m, tolérance 3–5 mm.\n- Humidité résiduelle.\n\n> DTU 52.1 : support propre, sec, plan, résistant.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 1, 1, 1, 'Analyser le support avant pose.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(131, 58, 'Chapes et ragréage', '# Chapes\n\n## Traditionnelle ciment\n- Dosage : 350 kg/m³.\n- Épaisseur mini : 5 cm (désolidarisée), 3 cm (adhérente).\n- Séchage : 1 semaine/cm.\n\n## Fluide\n- Ciment ou anhydrite.\n- Épaisseur 2–10 cm.\n- Surface parfaitement plane.\n\n## Ragréage\n- 1–10 mm par passe.\n- Ponçage après séchage.\n\n## Joints de fractionnement\nTous les 25–30 m² dans la chape.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 2, 0, 1, 'Support parfait pour le carrelage.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(132, 58, 'Étanchéité sous carrelage', '# Étanchéité\n\n## Réglementation\nDTU 52.1 et NF DTU 52.2 : étanchéité obligatoire sous carrelage des douches et salles de bain.\n\n## SEL (liquide)\n- Résine au rouleau, 2 couches croisées.\n- Bandes aux angles.\n\n## SEF (feuille)\n- Membrane PVC/bitumeuse.\n- Relevés périphériques 10 cm.\n\n## Zones\n- Douche italienne : sol + 20 cm murs.\n- Salle de bain : sol + 20 cm murs.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 25, 3, 0, 1, 'Protéger les pièces humides.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(133, 59, 'Méthodes de pose', '# Méthodes de pose\n\n## Pose collée\n- Mortier-colle, peigne 6–12 mm.\n- Double encollage pour carreaux > 30×30.\n\n## Pose scellée\n- Lit mortier 2–4 cm.\n- Pour terrasses et grands carreaux.\n\n## Pose sur plots\n- Plots réglables 2–15 cm.\n- Pour terrasses extérieures.\n\n## Joints\n| Format | Joint mini |\n|---|---|\n| ≤ 30×30 cm | 2 mm |\n| 30–60 cm | 3 mm |\n| > 60 cm | 5 mm |\n| Extérieur | 5–8 mm |', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 1, 0, 1, 'Collée, scellée, sur plots.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(134, 59, 'Découpe et calepinage', '# Découpe et calepinage\n\n## Calepinage\n- Éviter coupes < 1/3 carreau.\n- Centrer sur l\'axe de la pièce.\n\n## Outils\n- Coupe-carreau manuel (céramique).\n- Coupe-carreau électrique (grès, porcelaine).\n- Trépan diamanté (découpes rondes).\n\n## Découpes\n- À 45° (onglet).\n- En L (angles de porte).\n- Au fil à eau (complexes).', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 2, 0, 1, 'Optimiser la pose.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(135, 59, 'Jointoiement et finitions', '# Jointoiement\n\n## Mortiers\n- Ciment : économique.\n- Époxy : imperméable, anti-taches.\n- Souple polyuréthane : plancher chauffant.\n\n## Application\n1. Attendre 24 h après pose.\n2. Taloche caoutchouc (diagonale).\n3. Essuyer éponge humide (15–30 min).\n4. Nettoyage à sec (24–48 h).\n\n## Profils\n- Finition L, T, quart-de-rond.\n- Bandes de rive.\n- Seuil aluminium/bois/pierre.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, 0, 1, 'Joints propres et durables.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(136, 60, 'Moquette et dalles textiles', '# Moquette\n\n## Types\n- À velours (lisse, bureau).\n- À bouclettes (texturé, passage).\n- Haute densité (fort passage).\n\n## Pose\n1. Support plan et sec.\n2. Sous-couche acoustique.\n3. Acclimatation 24 h.\n4. Découpe et ajustement.\n5. Fixation double-face ou colle.\n\n## Dalles\n- Remplacement facile.\n- Joints alternés.\n- Sens de pose fléché au dos.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 1, 0, 1, 'Pose de moquette.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(137, 60, 'Revêtements PVC et linoléum', '# PVC et linoléum\n\n## PVC\n- Lés larges (2–4 m) collés.\n- Dalles clipsables.\n- Classement UPEC.\n\n## Linoléum\n- Naturel : huile lin, jute, résines.\n- Antistatique, antibactérien.\n- Hôpitaux, écoles, bureaux.\n\n## Pose PVC lés\n1. Acclimatation 24 h.\n2. Découpe avec surépaisseur.\n3. Encollage.\n4. Marouflage.\n5. Soudure (à froid ou à chaud).\n6. Profilés de finition.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 2, 0, 1, 'Sols vinyle et naturels.', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(138, 61, 'Étude de faisabilité', '# Faisabilité\n\n## Analyse\n- Site : accès, réseaux, nuisances.\n- Plans : architecte, structure, CVC, électricité.\n- Délais : planning prévisionnel.\n- Budget : estimation coûts.\n\n## Dossier technique\n- DCE, CCTP, BPU, DPGF.\n- Notes de calcul, plans d\'exécution.\n- DOE en fin de chantier.\n\n## Autorisations\n- Permis de construire.\n- Déclaration préalable.\n- Autorisations voirie.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 1, 1, 1, 'Préparer le projet avant l\'ouverture du chantier.', '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
(139, 61, 'Planification de chantier', '# Planification\n\n## Gantt\n- Tâches en barres horizontales.\n- Durée, antériorités, jalons.\n\n## PERT\n- Réseau logique des tâches.\n- Chemin critique = durée minimale.\n\n## Logiciels\n- MS Project, Primavera.\n- GanttProject, OpenProject.\n\n## Phases\n1. Installation de chantier.\n2. Terrassement/fondations.\n3. Structure.\n4. Second oeuvre.\n5. Finitions.\n6. Réception.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 2, 0, 1, 'Gantt, PERT et chemin critique.', '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
(140, 61, 'Gestion des approvisionnements', '# Approvisionnements\n\n## Plan\n- Défini à partir du planning.\n- Délais : béton 48 h, armatures 1 sem, menuiseries 4–6 sem.\n\n## Stockage\n- Zone stable, drainée, sécurisée.\n- Couvert (ciment, plâtre, bois).\n- Rotation FIFO.\n\n## Réception\n- Vérification quantitative et qualitative.\n- Réserves sur bon de livraison.\n- Photo des anomalies.\n\n## Suivi\n- Tableau consommations.\n- Détection écarts (vol, perte, surconsommation).', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, 0, 1, 'Logistique et suivi des matériaux.', '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
(141, 62, 'Direction et coordination', '# Direction des équipes\n\n## Rôles\n- Chef de chantier : exécution terrain.\n- Conducteur de travaux : gestion technique/financière.\n- Compagnons : exécution.\n\n## Communication\n- Réunion hebdomadaire.\n- Ordre de service (modifications).\n- Main courante (journal quotidien).\n\n## Sous-traitance\n- Sélection : références, capacité.\n- Contrat : prestations, délais, pénalités.\n- Coordination interfaces.\n\n## Conflits\n- Médiation active.\n- Réunion de crise.\n- Signalement hiérarchique.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 1, 0, 1, 'Animer les équipes et sous-traitants.', '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
(142, 62, 'Suivi budgétaire', '# Suivi budgétaire\n\n## Budget prévisionnel\n- Décompte mensuel (quantités × PU).\n- Variation coûts par lot.\n- Révision de prix (indice BT).\n\n## Postes\n| Poste | Poids |\n|---|---|\n| Main-d\'oeuvre | 30–40 % |\n| Matériaux | 25–35 % |\n| Sous-traitance | 15–25 % |\n| Location | 5–10 % |\n| Frais généraux | 5–10 % |\n\n## Réunions\n- Avancement, points bloquants.\n- Validation situations.\n- Planning actualisé.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 2, 0, 1, 'Maîtriser le budget chantier.', '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
(143, 62, 'Réunions et reporting', '# Réunions\n\n## Types\n- Kick-off : présentation projet.\n- Hebdomadaire : suivi + sécurité.\n- Coordination : interfaces techniques.\n- Clôture : bilan et réception.\n\n## Ordre du jour\n1. Décisions précédentes.\n2. Avancement par lot.\n3. Sécurité/incidents.\n4. Planning.\n5. Modifications/avenants.\n6. Questions diverses.\n\n## CR\n- Diffusé sous 48 h.\n- Tableau : Action, Responsable, Date.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 25, 3, 0, 1, 'Comptes-rendus efficaces.', '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
(144, 63, 'Réglementation sécurité', '# Réglementation\n\n## Textes\n- Code du travail L. 4121-1 à 5.\n- Décret 2008-244.\n- R. 4534-1 (BTP).\n\n## Documents\n- **PPSPS** : par entreprise.\n- **PGCSPS** : plusieurs entreprises.\n- Registre sécurité : accidents, incidents.\n- Registre vérification EPI/échafaudages.\n- **DUERP** : document unique.\n\n## Acteurs\n- Coordonnateur SPS (> 5000 h·j).\n- CARSAT, OPPBTP, Inspection travail.\n\n## Sanctions\n- Absence PPSPS : amende ≤ 10 000 €.\n- Absence DUERP : amende ≤ 1 500 €.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35, 1, 0, 1, 'PPSPS, registre, plan de prévention.', '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
(145, 63, 'Évaluation des risques', '# Évaluation des risques\n\n## Démarche\n1. Identifier les dangers.\n2. Analyser : gravité × probabilité × exposition.\n3. Hiérarchiser.\n4. Planifier actions.\n5. Suivre et réévaluer.\n\n## Risques BTP\n| Risque | Gravité | Fréquence |\n|---|---|---|\n| Chute hauteur | Très élevée | Très fréquente |\n| Électrocution | Élevée | Rare |\n| Écrasement | Élevée | Peu fréquente |\n| Manutention | Moyenne | Très fréquente |\n| Silice | Élevée (LT) | Quotidienne |\n\n## Cotation\nCriticité = Gravité × Probabilité (seuil ≥ 8/16).', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 2, 0, 1, 'Identifier et hiérarchiser les risques.', '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
(146, 63, 'Équipements de protection', '# Équipements de protection\n\n## EPC (collective)\n- Garde-corps : ≥ 100 cm, lisse 45 cm, plinthe.\n- Filets sécurité : mailles ≤ 10 cm.\n- Échafaudages : montage par personnel qualifié.\n\n## EPI (individuelle)\n- Casque (norme EN 397).\n- Chaussures sécurité (EN 345).\n- Harnais anti-chute (EN 361).\n- Gants, lunettes, protections auditives.\n\n## Principes\n- EPC prioritaire sur EPI.\n- Vérification périodique obligatoire.\n- Formation des utilisateurs.', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 3, 0, 1, 'EPC et EPI sur le chantier.', '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
(147, 64, 'Introduction aux Grands Modèles de Langage (LLMs)', '# Introduction aux Grands Modèles de Langage (LLMs)\n\n## Qu\'est-ce qu\'un LLM ?\n\nUn **Large Language Model (LLM)** est un réseau de neurones entraîné sur des quantités massives de texte. Il apprend à prédire le mot suivant dans une séquence, ce qui lui permet de générer du texte cohérent, de résumer, de traduire et de raisonner.\n\n## Architecture Transformer\n\nL\'architecture **Transformer** (Vaswani et al., 2017) est le fondement de tous les LLMs modernes. Ses composants clés :\n\n- **Self-attention** — Permet au modèle de pondérer l\'importance de chaque mot par rapport aux autres.\n- **Multi-head attention** — Plusieurs têtes d\'attention capturent différentes relations linguistiques.\n- **Feed-forward layers** — Couches de transformation non-linéaires.\n- **Positional encoding** — Ajoute une information de position dans la séquence.\n\n## Tokenisation\n\nLes LLMs ne lisent pas du texte brut mais des **tokens** :\n- Un token peut être un mot, une partie de mot ou un caractère.\n- GPT-4 utilise un vocabulaire d\'environ 100 000 tokens.\n- La tokenisation impacte le coût et la latence (entrée/sortie comptée en tokens).\n\n## Entraînement\n\n1. **Pre-training** — Apprentissage non supervisé sur des téraoctets de texte (coût : plusieurs millions de dollars).\n2. **Fine-tuning supervisé (SFT)** — Ajustement sur des paires question/réponse.\n3. **RLHF (Reinforcement Learning from Human Feedback)** — Alignement avec les préférences humaines.\n\n## Modèles populaires (2024-2026)\n\n| Modèle | Créateur | Particularité |\n|--------|----------|---------------|\n| GPT-4o / o3 | OpenAI | Multimodal, raisonnement avancé |\n| Claude 3.5 / 4 | Anthropic | Long contexte, sécurité, MCP natif |\n| Gemini 2.0 | Google | Intégration Google, multimodal |\n| Llama 3 / 4 | Meta (Mozilla) | Open source, déployable on-premise |\n| DeepSeek | DeepSeek | Performance coût, open-weight |\n| Mistral / Mixtral | Mistral AI | Efficacité, français, open-source |\n\n## Capacités clés\n\n- Génération de texte et code\n- Résumé et extraction\n- Traduction\n- Analyse de sentiment\n- Raisonnement multi-étapes (chain-of-thought)\n- Apprentissage en contexte (few-shot, zero-shot)', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 25, 1, 1, 1, 'Comprendre le fonctionnement interne des LLMs, leur entraînement et leurs capacités.', '2026-07-28 00:42:34', '2026-07-28 00:42:34');
