INSERT INTO `formations` (`id`, `title`, `slug`, `short_description`, `description`, `image`, `price`, `duration_hours`, `difficulty_level`, `is_active`, `is_featured`, `is_certifying`, `tags`, `created_at`, `updated_at`) VALUES
(1, 'Développement Web Full Stack', 'developpement-web-full-stack', 'Apprenez à créer des applications web modernes de A à Z avec Laravel, React et Tailwind CSS.', 'Cette formation complète vous guide du débutant jusqu\'au développeur Full Stack professionnel. Vous maîtriserez le frontend avec React et Tailwind CSS, le backend avec Laravel, la gestion des bases de données, l\'authentification, les API RESTful, et le déploiement. Chaque module contient des projets pratiques pour consolider vos apprentissages.', NULL, 150000.00, 120, 'beginner', 1, 1, 0, '[\"Laravel\",\"React\",\"Tailwind CSS\",\"PHP\",\"JavaScript\",\"Full Stack\"]', '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(2, 'Marketing Digital & Stratégie Social Media', 'marketing-digital-strategie-social-media', 'Maîtrisez les stratégies marketing digitales et la gestion des réseaux sociaux.', 'Plongez dans l\'univers du marketing digital. Cette formation couvre le SEO, le SEA, le marketing de contenu, la gestion des réseaux sociaux, l\'email marketing, l\'analyse de données, et les stratégies de conversion. Vous apprendrez à créer des campagnes efficaces et à mesurer leur performance avec des outils professionnels.', NULL, 120000.00, 80, 'intermediate', 1, 1, 0, '[\"Marketing Digital\",\"SEO\",\"Social Media\",\"Google Ads\",\"Content Marketing\"]', '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(3, 'Data Science & Analyse de Données avec Python', 'data-science-analyse-de-donnees-avec-python', 'Devenez expert en analyse de données et machine learning avec Python.', 'Une formation intensive qui vous apprend à manipuler, analyser et visualiser des données avec Python. Vous explorerez NumPy, Pandas, Matplotlib, Scikit-learn, et les fondamentaux du machine learning. Idéal pour les analystes, ingénieurs et toute personne souhaitant se lancer dans la data science.', NULL, 180000.00, 100, 'advanced', 1, 0, 0, '[\"Python\",\"Data Science\",\"Machine Learning\",\"Pandas\",\"NumPy\",\"Analyse de donn\\u00e9es\"]', '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(4, 'Cybersécurité & Ethical Hacking', 'cybersecurite-ethical-hacking', 'Protégez les systèmes et découvrez les techniques des hackers éthiques.', 'Cette formation complète vous plonge dans l\'univers de la cybersécurité. Vous apprendrez les fondamentaux de la sécurité informatique, les techniques de pentest, l\'analyse de vulnérabilités, la sécurisation des réseaux et des applications web. Vous utiliserez des outils comme Kali Linux, Metasploit, Wireshark et Burp Suite pour des missions pratiques.', NULL, 200000.00, 110, 'advanced', 1, 1, 0, '[\"Cybers\\u00e9curit\\u00e9\",\"Ethical Hacking\",\"Pentest\",\"Kali Linux\",\"S\\u00e9curit\\u00e9 R\\u00e9seau\"]', '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(5, 'Cloud Computing & DevOps', 'cloud-computing-devops', 'Maîtrisez le cloud AWS, Docker, Kubernetes et les pratiques DevOps.', 'Une formation intensive sur le cloud computing et les pratiques DevOps modernes. Vous découvrirez AWS (EC2, S3, Lambda), la conteneurisation avec Docker, l\'orchestration avec Kubernetes, et les pipelines CI/CD. Idéal pour les développeurs et administrateurs systèmes souhaitant monter en compétence.', NULL, 160000.00, 90, 'advanced', 1, 0, 0, '[\"Cloud\",\"DevOps\",\"AWS\",\"Docker\",\"Kubernetes\",\"CI\\/CD\"]', '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(6, 'Initiation à l\'Algorithmique & Logique de Programmation', 'initiation-a-lalgorithmique-logique-de-programmation', 'Les bases de l\'algorithmique pour débuter en programmation.', 'Cette formation gratuite vous initie aux concepts fondamentaux de l\'algorithmique et de la logique de programmation. Vous apprendrez les structures de contrôle, les types de données, les algorithmes de tri et de recherche, et la résolution de problèmes. Aucun prérequis technique nécessaire.', NULL, NULL, 30, 'beginner', 1, 0, 0, '[\"Algorithmique\",\"Programmation\",\"Logique\",\"D\\u00e9butant\"]', '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(7, 'Excel & Analyse de Données pour les Affaires', 'excel-analyse-de-donnees-pour-les-affaires', 'Maîtrisez Excel pour l\'analyse de données professionnelle.', 'Une formation pratique et gratuite pour maîtriser Excel dans un contexte professionnel. Vous apprendrez les formules avancées, les tableaux croisés dynamiques, les graphiques, la mise en forme conditionnelle, et les macros VBA. Parfait pour les professionnels souhaitant améliorer leur productivité.', NULL, NULL, 25, 'beginner', 1, 1, 0, '[\"Excel\",\"Analyse de donn\\u00e9es\",\"Tableaux crois\\u00e9s\",\"VBA\",\"Productivit\\u00e9\"]', '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(8, 'Design Thinking & Innovation', 'design-thinking-innovation', 'Apprenez à innover avec la méthode Design Thinking.', 'Découvrez le Design Thinking, une méthode de résolution de problèmes centrée sur l\'humain. Cette formation gratuite vous guide à travers les 5 étapes : empathie, définition, idéation, prototypage et test. Idéal pour les entrepreneurs, chefs de projet et créatifs.', NULL, NULL, 20, 'beginner', 1, 0, 0, '[\"Design Thinking\",\"Innovation\",\"Cr\\u00e9ativit\\u00e9\",\"Prototypage\",\"M\\u00e9thode Agile\"]', '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(9, 'Communication & Prise de Parole en Public', 'communication-prise-de-parole-en-public', 'Développez votre aisance à l\'oral et votre charisme.', 'Apprenez à communiquer efficacement et à captiver votre auditoire. Cette formation couvre les techniques de prise de parole, la gestion du trac, la communication non verbale, l\'art du storytelling, et la préparation de présentations percutantes. Idéal pour les professionnels et les étudiants.', NULL, NULL, 15, 'beginner', 1, 0, 0, '[\"Communication\",\"Prise de parole\",\"Storytelling\",\"Pr\\u00e9sentation\",\"Charisme\"]', '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(10, 'Gestion de Projet Agile avec Scrum', 'gestion-de-projet-agile-avec-scrum', 'Maîtrisez la méthodologie Scrum pour gérer vos projets.', 'Une formation gratuite complète sur la gestion de projet agile avec Scrum. Vous découvrirez les rôles (Scrum Master, Product Owner, Developers), les cérémonies (Sprint Planning, Daily Scrum, Sprint Review, Rétrospective), et les artefacts (Product Backlog, Sprint Backlog, Incrément). Préparez-vous à passer la certification Scrum Master.', NULL, NULL, 20, 'intermediate', 1, 1, 0, '[\"Scrum\",\"Agile\",\"Gestion de projet\",\"Certification\",\"Productivit\\u00e9\"]', '2026-07-28 00:42:29', '2026-07-28 00:42:29'),
(11, 'Pilotage des risques opérationnels — Parcours professionnel', 'pilotage-des-risques-operationnels-parcours-professionnel', 'Construisez un dispositif de maîtrise des risques, de la cartographie au plan de continuité.', 'Un parcours professionnel fondé sur des cas réels, des supports téléchargeables et une évaluation obligatoire après chaque section.', 'demo/professional-risk-management.jpg', 0.00, 8, 'intermediate', 1, 1, 1, '[\"risques\",\"audit\",\"gouvernance\",\"professionnel\"]', '2026-07-28 00:42:31', '2026-07-28 00:42:31'),
(12, 'Maçonnerie Générale & Techniques de Construction', 'maconnerie-generale-techniques-de-construction', 'Maîtrisez les techniques fondamentales de la maçonnerie : fondations, élévation des murs, planchers et dallages.', 'Cette formation complète vous forme aux gestes et techniques essentiels du métier de maçon. Vous apprendrez à réaliser des fondations solides, à élever des murs en parpaings, briques et pierres, à couler des dallages et à poser des planchers.', NULL, NULL, 80, 'beginner', 1, 1, 1, '[\"ma\\u00e7onnerie\",\"fondations\",\"construction\",\"mur\",\"dallage\",\"BTP\"]', '2026-07-28 00:42:31', '2026-07-28 00:42:32'),
(13, 'Électricité Bâtiment & Courants Faibles', 'electricite-batiment-courants-faibles', 'Devenez électricien qualifié : installation résidentielle, courants faibles et domotique.', 'Formation complète aux métiers de l\'électricité du bâtiment : fondamentaux, câblage résidentiel et tertiaire, courants faibles (VDI, alarmes) et domotique. Conforme à la norme NF C 15-100.', NULL, NULL, 75, 'beginner', 1, 1, 1, '[\"\\u00e9lectricit\\u00e9\",\"courants faibles\",\"domotique\",\"NF C 15-100\",\"installation\",\"BTP\"]', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(14, 'Plomberie & Installation Sanitaire', 'plomberie-installation-sanitaire', 'Réseaux d\'eau, d\'évacuation et pose d\'appareils sanitaires.', 'Formation complète à la plomberie et au sanitaire : réseaux d\'alimentation (cuivre, PER, multicouche), évacuation et assainissement, pose et raccordement des appareils sanitaires. Conforme aux DTU applicables.', NULL, NULL, 70, 'beginner', 1, 0, 1, '[\"plomberie\",\"sanitaire\",\"chauffage\",\"eau\",\"\\u00e9vacuation\",\"BTP\"]', '2026-07-28 00:42:32', '2026-07-28 00:42:32'),
(15, 'Menuiserie & Ébénisterie', 'menuiserie-ebenisterie', 'Travail du bois, assemblages, fabrication et pose de menuiseries.', 'Formation complète aux métiers du bois : essences, usinage et assemblage, fabrication de fenêtres, portes, escaliers et meubles sur mesure, finitions (vernis, cire, peinture).', NULL, NULL, 90, 'intermediate', 1, 1, 1, '[\"menuiserie\",\"\\u00e9b\\u00e9nisterie\",\"bois\",\"assemblage\",\"agencement\",\"BTP\"]', '2026-07-28 00:42:32', '2026-07-28 00:42:33'),
(16, 'Peinture & Finitions en Bâtiment', 'peinture-finitions-en-batiment', 'Préparation des supports, techniques d\'application et finitions décoratives.', 'Formation aux techniques professionnelles de peinture : préparation des supports, application peinture/papier peint, effets décoratifs (patine, stuc, béton ciré), finitions boiseries et sols.', NULL, NULL, 60, 'beginner', 1, 0, 1, '[\"peinture\",\"finition\",\"enduit\",\"d\\u00e9coration\",\"rev\\u00eatement\",\"BTP\"]', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(17, 'Soudure & Métallerie', 'soudure-metallerie', 'Procédés de soudage, métallerie du bâtiment et ferronnerie.', 'Formation aux techniques de soudage (arc, MIG/MAG, TIG, oxycoupage) et à la métallerie : portails, garde-corps, charpentes métalliques et ferronnerie décorative.', NULL, NULL, 85, 'intermediate', 1, 0, 1, '[\"soudure\",\"m\\u00e9tallerie\",\"ferronnerie\",\"soudage\",\"MIG\",\"TIG\",\"BTP\"]', '2026-07-28 00:42:33', '2026-07-28 00:42:33'),
(18, 'Carrelage & Revêtements de Sols', 'carrelage-revetements-de-sols', 'Pose de carrelage, chapes, étanchéité et revêtements souples.', 'Formation aux métiers du carrelage : préparation des supports (chapes, ragréage), pose du carrelage (collée, scellée, sur plots), jointoiement, et revêtements souples (moquette, PVC, parquet flottant).', NULL, NULL, 65, 'beginner', 1, 0, 1, '[\"carrelage\",\"rev\\u00eatement\",\"sol\",\"chape\",\"\\u00e9tanch\\u00e9it\\u00e9\",\"BTP\"]', '2026-07-28 00:42:33', '2026-07-28 00:42:34'),
(19, 'Gestion de Chantier & Sécurité BTP', 'gestion-de-chantier-securite-btp', 'Planification, conduite de travaux, sécurité et prévention.', 'Formation à la gestion de chantier et à la sécurité BTP : organisation et planification, direction des équipes, suivi budgétaire, réglementation sécurité (PPSPS, DUERP), évaluation des risques, EPI/EPC.', NULL, NULL, 70, 'intermediate', 1, 1, 1, '[\"gestion chantier\",\"s\\u00e9curit\\u00e9\",\"BTP\",\"conduite travaux\",\"pr\\u00e9vention\",\"planification\"]', '2026-07-28 00:42:34', '2026-07-28 00:42:34'),
(20, 'Intelligence Artificielle, Agents Autonomes & Protocole MCP', 'ia-agents-autonomes-protocole-mcp', 'Maîtrisez les fondamentaux de l\'IA générative, concevez des agents autonomes et implémentez des serveurs MCP avec Laravel.', '## Objectifs de la formation\n\nComprendre et maîtriser l\'écosystème moderne de l\'intelligence artificielle :\n\n- **Fondamentaux des LLMs** — Architecture Transformer, tokenisation, mécanismes d\'attention.\n- **RAG et embeddings** — Recherche sémantique, vectorisation et augmentation contextuelle.\n- **Agents autonomes** — Conception d\'agents avec outils, mémoire et planification.\n- **Model Context Protocol (MCP)** — Création de serveurs MCP avec Laravel, exposition d\'outils et de ressources.\n- **Déploiement sécurisé** — Authentification, rate limiting, monitoring et intégration avec les clients MCP.\n\nÀ l\'issue de cette formation, vous serez capable de développer des solutions IA complètes, des chatbots RAG aux serveurs MCP interopérables.', NULL, 0.00, 60, 'intermediate', 1, 0, 1, '[\"IA\",\"Intelligence Artificielle\",\"MCP\",\"Agents\",\"LLM\",\"Laravel\",\"RAG\",\"Automatisation\"]', '2026-07-28 00:42:34', '2026-07-28 00:42:34');
