INSERT INTO `questions` (`id`, `exam_id`, `question_text`, `question_type`, `points`, `order_position`, `explanation`, `image`, `is_required`, `created_at`, `updated_at`) VALUES
(1, 1, 'Quel langage est utilisé pour structurer le contenu d\'une page web ?', 'single_choice', 10, 1, 'HTML (HyperText Markup Language) est le langage de balisage standard pour créer des pages web.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(2, 1, 'Qu\'est-ce que le Flexbox en CSS ?', 'single_choice', 10, 2, 'Flexbox est un module de mise en page CSS qui permet d\'aligner et de distribuer efficacement les éléments dans un conteneur.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(3, 1, 'En PHP 8, comment déclarez-vous une énumération ?', 'single_choice', 10, 3, 'Depuis PHP 8.1, on utilise le mot-clé \"enum\" suivi du nom et éventuellement du type.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(4, 1, 'Quel est le rôle d\'un middleware dans Laravel ?', 'single_choice', 10, 4, 'Les middlewares filtrent les requêtes HTTP entrantes. Ils sont idéaux pour l\'authentification, la journalisation, etc.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(5, 1, 'Quels sont les hooks React fondamentaux ? (Plusieurs réponses possibles)', 'multiple_choice', 15, 5, 'useState, useEffect, useContext et useReducer sont les hooks fondamentaux de React.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(6, 1, 'Tailwind CSS est un framework CSS utility-first.', 'true_false', 5, 6, 'Vrai. Tailwind CSS adopte une approche utility-first contrairement à Bootstrap qui est basé sur des composants.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(7, 1, 'En HTTP, une requête GET transmet les paramètres dans l\'URL tandis qu\'une requête POST les transmet dans le corps de la requête.', 'true_false', 10, 7, 'GET récupère des données (visible dans l\'URL, limité en taille), POST envoie des données (dans le corps, pas de limite de taille).', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(8, 1, 'Quelle commande Artisan permet de créer une migration ?', 'single_choice', 10, 8, 'php artisan make:migration est la commande pour créer une nouvelle migration.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(9, 1, 'Vite propose un rechargement à chaud (HMR) ultra-rapide et des builds optimisés avec Rollup.', 'true_false', 10, 9, 'Vite offre un rechargement à chaud ultra-rapide (HMR) et des builds optimisés avec Rollup.', NULL, 0, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(10, 1, 'Quel service cloud est utilisé pour déployer une application Laravel avec Forge ?', 'single_choice', 10, 10, 'Laravel Forge supporte AWS, DigitalOcean, Linode, Vultr, et Hetzner comme fournisseurs cloud.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(11, 2, 'Que signifie SEO ?', 'single_choice', 10, 1, 'SEO signifie Search Engine Optimization (Optimisation pour les moteurs de recherche).', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(12, 2, 'Quel est l\'objectif principal du marketing de contenu ?', 'single_choice', 10, 2, 'Le marketing de contenu vise à attirer et engager une audience cible en créant du contenu pertinent et de valeur.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(13, 2, 'Quels sont les facteurs de ranking Google les plus importants ? (Plusieurs réponses)', 'multiple_choice', 15, 3, 'La qualité du contenu, les backlinks, l\'expérience utilisateur et la vitesse de chargement sont des facteurs clés.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(14, 2, 'Le CPC (Coût Par Clic) est une métrique utilisée uniquement pour le SEO.', 'true_false', 5, 4, 'Faux. Le CPC est une métrique utilisée pour les campagnes publicitaires payantes (SEA), pas pour le SEO.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(15, 2, 'Décrivez les étapes pour créer une campagne Google Ads performante.', 'single_choice', 25, 5, 'Définir les objectifs, choisir les mots-clés, créer des annonces, définir le budget, cibler l\'audience, et analyser les performances.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(16, 2, 'Qu\'est-ce qu\'un taux d\'engagement sur les réseaux sociaux ?', 'single_choice', 10, 6, 'Le taux d\'engagement mesure les interactions (likes, commentaires, partages) rapportées au nombre d\'abonnés ou d\'impressions.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(17, 2, 'Citez trois outils de gestion des réseaux sociaux.', 'single_choice', 10, 7, 'Hootsuite, Buffer, Later, Sprout Social, et HubSpot sont des outils populaires.', NULL, 0, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(18, 2, 'Qu\'est-ce que le retargeting ?', 'single_choice', 15, 8, 'Le retargeting consiste à cibler les utilisateurs qui ont déjà visité votre site avec des publicités personnalisées.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(19, 3, 'Quelle bibliothèque Python est utilisée pour le calcul numérique ?', 'single_choice', 10, 1, 'NumPy est la bibliothèque fondamentale pour le calcul numérique en Python.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(20, 3, 'À quoi sert la méthode groupby() dans Pandas ?', 'single_choice', 10, 2, 'groupby() permet de regrouper les données selon une ou plusieurs colonnes pour appliquer des fonctions d\'agrégation.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(21, 3, 'Quels sont les types d\'apprentissage automatique ? (Plusieurs réponses)', 'multiple_choice', 15, 3, 'Les trois principaux types sont l\'apprentissage supervisé, non supervisé et par renforcement.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(22, 3, 'Dans un arbre de décision, plus la profondeur est grande, meilleur est le modèle.', 'true_false', 5, 4, 'Faux. Une trop grande profondeur entraîne du surapprentissage (overfitting). Il faut trouver le bon équilibre.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(23, 3, 'Expliquez la différence entre le surapprentissage (overfitting) et le sous-apprentissage (underfitting).', 'single_choice', 20, 5, 'Overfitting : le modèle apprend trop bien les données d\'entraînement mais généralise mal. Underfitting : le modèle est trop simple et ne capture pas les patterns.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(24, 3, 'Qu\'est-ce que la validation croisée (cross-validation) ?', 'single_choice', 10, 6, 'La validation croisée divise les données en plusieurs plis pour évaluer la performance du modèle de manière robuste.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(25, 3, 'Quelle métrique est appropriée pour évaluer un modèle de classification binaire déséquilibré ?', 'single_choice', 10, 7, 'Le F1-score est la meilleure métrique pour les données déséquilibrées car il combine précision et rappel.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(26, 3, 'Citez deux algorithmes de clustering.', 'single_choice', 10, 8, 'K-Means, DBSCAN, Clustering hiérarchique, et Gaussian Mixture Models sont des algorithmes de clustering courants.', NULL, 0, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(27, 3, 'Quelle est la différence entre une variable catégorielle et une variable continue ?', 'single_choice', 10, 9, 'Une variable catégorielle prend des valeurs discrètes (ex: couleur), une variable continue peut prendre n\'importe quelle valeur dans un intervalle.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(28, 3, 'Qu\'est-ce que le théorème de Bayes et à quoi sert-il en ML ?', 'single_choice', 20, 10, 'Le théorème de Bayes décrit la probabilité conditionnelle. Il est utilisé dans les classifieurs naïfs de Bayes pour la classification.', NULL, 1, '2026-07-28 00:42:30', '2026-07-28 00:42:30'),
(29, 4, 'Quel acteur fournit une assurance indépendante ?', 'single_choice', 5, 1, 'Consultez le support de la section pour revoir ce point.', NULL, 1, '2026-07-28 00:42:31', '2026-07-28 00:42:31'),
(30, 4, 'Les métiers constituent la première ligne de maîtrise.', 'true_false', 5, 2, 'Consultez le support de la section pour revoir ce point.', NULL, 1, '2026-07-28 00:42:31', '2026-07-28 00:42:31'),
